pub fn run_param_fns(
    script_path: &str,
    fns: &[&str],
    args: &[String],
    envs: HashMap<String, String>,
) -> Option<Vec<String>> {
    let shell = get_shell_path()?;
    let mut outputs = Vec::new();
    for f in fns {
        let mut cmd = std::process::Command::new(&shell);
        cmd.arg("--noprofile").arg("--norc").arg(script_path).arg("___internal___").arg(f);
        cmd.args(args);
        cmd.env("ARGC_OS", std::env::consts::OS);
        for (k, v) in &envs {
            cmd.env(k, v);
        }
        cmd.stdin(std::process::Stdio::null());
        cmd.stderr(std::process::Stdio::null());
        let output = cmd.output().ok()?;
        outputs.push(String::from_utf8_lossy(&output.stdout).to_string());
    }
    Some(outputs)
}

// ---------- text wrapping (textwrap-like optimal fit) -----------

struct Fragment {
    width: f64,
    whitespace_width: f64,
    penalty_width: f64,
    text: String,
    whitespace: String,
    penalty: String,
}

fn char_width(c: char) -> usize {
    if c.is_control() {
        0
    } else {
        1
    }
}

fn str_width(s: &str) -> usize {
    s.chars().map(char_width).sum()
}

fn find_words(line: &str) -> Vec<Fragment> {
    let mut words = Vec::new();
    let mut start = 0;
    let mut in_whitespace = false;
    let chars: Vec<(usize, char)> = line.char_indices().collect();
    for (idx, ch) in chars.iter() {
        let is_ws = *ch == ' ';
        if in_whitespace && !is_ws {
            // word ended
            let word = &line[start..*idx];
            words.push(make_word(word));
            start = *idx;
            in_whitespace = false;
        } else if is_ws {
            in_whitespace = true;
        }
    }
    if start < line.len() {
        words.push(make_word(&line[start..]));
    }
    words
}

fn make_word(word: &str) -> Fragment {
    let trimmed = word.trim_end_matches(' ');
    let ws = &word[trimmed.len()..];
    Fragment {
        width: str_width(trimmed) as f64,
        whitespace_width: ws.len() as f64,
        penalty_width: 0.0,
        text: trimmed.to_string(),
        whitespace: ws.to_string(),
        penalty: String::new(),
    }
}

fn split_hyphens(frag: Fragment) -> Vec<Fragment> {
    let word = &frag.text;
    let chars: Vec<char> = word.chars().collect();
    let mut splits = Vec::new();
    let mut byte_idx = 0;
    for (i, c) in chars.iter().enumerate() {
        let clen = c.len_utf8();
        if *c == '-' && i > 0 && i + 1 < chars.len() {
            let prev = chars[i - 1];
            let next = chars[i + 1];
            if prev.is_alphanumeric() && next.is_alphanumeric() {
                splits.push(byte_idx + clen);
            }
        }
        byte_idx += clen;
    }
    if splits.is_empty() {
        return vec![frag];
    }
    let mut out = Vec::new();
    let mut prev = 0;
    for s in splits {
        let part = &word[prev..s];
        out.push(Fragment {
            width: str_width(part) as f64,
            whitespace_width: 0.0,
            penalty_width: 0.0,
            text: part.to_string(),
            whitespace: String::new(),
            penalty: String::new(),
        });
        prev = s;
    }
    let last = &word[prev..];
    out.push(Fragment {
        width: str_width(last) as f64,
        whitespace_width: frag.whitespace_width,
        penalty_width: 0.0,
        text: last.to_string(),
        whitespace: frag.whitespace.clone(),
        penalty: String::new(),
    });
    out
}

fn break_words(frags: Vec<Fragment>, width: usize) -> Vec<Fragment> {
    let mut out = Vec::new();
    for frag in frags {
        if (frag.width as usize) > width {
            let chars: Vec<char> = frag.text.chars().collect();
            let mut start = 0;
            let mut cur_w = 0;
            let mut parts: Vec<String> = Vec::new();
            let mut cur = String::new();
            for c in chars.iter() {
                let cw = char_width(*c);
                if cur_w + cw > width && !cur.is_empty() {
                    parts.push(cur.clone());
                    cur.clear();
                    cur_w = 0;
                }
                cur.push(*c);
                cur_w += cw;
                start += 1;
            }
            let _ = start;
            if !cur.is_empty() {
                parts.push(cur);
            }
            let n = parts.len();
            for (i, p) in parts.into_iter().enumerate() {
                if i + 1 == n {
                    out.push(Fragment {
                        width: str_width(&p) as f64,
                        whitespace_width: frag.whitespace_width,
                        penalty_width: 0.0,
                        text: p,
                        whitespace: frag.whitespace.clone(),
                        penalty: String::new(),
                    });
                } else {
                    out.push(Fragment {
                        width: str_width(&p) as f64,
                        whitespace_width: 0.0,
                        penalty_width: 0.0,
                        text: p,
                        whitespace: String::new(),
                        penalty: String::new(),
                    });
                }
            }
        } else {
            out.push(frag);
        }
    }
    out
}

fn wrap_optimal_fit(frags: &[Fragment], line_width: f64) -> Vec<(usize, usize)> {
    let n = frags.len();
    let mut widths = Vec::with_capacity(n + 1);
    let mut w = 0.0;
    widths.push(w);
    for f in frags {
        w += f.width + f.whitespace_width;
        widths.push(w);
    }
    let nline_penalty = 1000.0;
    let overflow_penalty = 50_000.0;
    let short_last_line_fraction = 4.0;
    let short_last_line_penalty = 25.0;
    let hyphen_penalty = 25.0;
    let target_width = line_width.max(1.0);
    // minima[j] = (best i, cost)
    let mut minima: Vec<(usize, f64)> = vec![(0, 0.0); n + 1];
    for j in 1..=n {
        let mut best: Option<(usize, f64)> = None;
        for i in 0..j {
            let lw = widths[j] - widths[i] - frags[j - 1].whitespace_width + frags[j - 1].penalty_width;
            let mut cost = minima[i].1 + nline_penalty;
            if lw > target_width {
                let overflow = lw - target_width;
                cost += overflow * overflow_penalty;
            } else if j < n {
                let gap = target_width - lw;
                cost += gap * gap;
            } else if i + 1 == j && lw < target_width / short_last_line_fraction {
                cost += short_last_line_penalty;
            }
            if frags[j - 1].penalty_width > 0.0 {
                cost += hyphen_penalty;
            }
            match best {
                None => best = Some((i, cost)),
                Some((_, bc)) => {
                    if cost < bc {
                        best = Some((i, cost));
                    }
                }
            }
        }
        minima[j] = best.unwrap();
    }
    let mut lines = Vec::new();
    let mut pos = n;
    loop {
        let start = minima[pos].0;
        lines.push((start, pos));
        pos = start;
        if pos == 0 {
            break;
        }
    }
    lines.reverse();
    lines
}

pub fn wrap_text(text: &str, width: usize) -> Vec<String> {
    let mut result = Vec::new();
    for line in text.split('\n') {
        let words = find_words(line);
        let mut frags = Vec::new();
        for w in words {
            frags.extend(split_hyphens(w));
        }
        let frags = break_words(frags, width);
        if frags.is_empty() {
            result.push(String::new());
            continue;
        }
        let lines = wrap_optimal_fit(&frags, width as f64);
        for (start, end) in lines {
            let mut s = String::new();
            for (k, f) in frags[start..end].iter().enumerate() {
                s.push_str(&f.text);
                if k + 1 < end - start {
                    s.push_str(&f.whitespace);
                } else {
                    s.push_str(&f.penalty);
                }
            }
            result.push(s);
        }
    }
    result
}

pub fn wrap_text_opt(text: &str, width: Option<usize>) -> Vec<String> {
    match width {
        Some(w) => wrap_text(text, w),
        None => text.split('\n').map(|v| v.to_string()).collect(),
    }
}

// ---------------- JSON ----------------

#[derive(Debug, Clone)]
pub enum Json {
    Null,
    Bool(bool),
    Num(i64),
    Str(String),
    Arr(Vec<Json>),
    Obj(Vec<(String, Json)>),
}

impl Json {
    pub fn str<S: AsRef<str>>(s: S) -> Json {
        Json::Str(s.as_ref().to_string())
    }
    pub fn opt_str(s: &Option<String>) -> Json {
        match s {
            Some(v) => Json::Str(v.clone()),
            None => Json::Null,
        }
    }
    pub fn strs(v: &[String]) -> Json {
        Json::Arr(v.iter().map(|s| Json::Str(s.clone())).collect())
    }
    pub fn to_pretty(&self) -> String {
        let mut out = String::new();
        self.write(&mut out, 0);
        out
    }
    fn write(&self, out: &mut String, indent: usize) {
        match self {
            Json::Null => out.push_str("null"),
            Json::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
            Json::Num(n) => out.push_str(&n.to_string()),
            Json::Str(s) => json_escape_str(s, out),
            Json::Arr(items) => {
                if items.is_empty() {
                    out.push_str("[]");
                    return;
                }
                out.push_str("[\n");
                for (i, item) in items.iter().enumerate() {
                    out.push_str(&"  ".repeat(indent + 1));
                    item.write(out, indent + 1);
                    if i + 1 < items.len() {
                        out.push(',');
                    }
                    out.push('\n');
                }
                out.push_str(&"  ".repeat(indent));
                out.push(']');
            }
            Json::Obj(items) => {
                if items.is_empty() {
                    out.push_str("{}");
                    return;
                }
                out.push_str("{\n");
                for (i, (k, v)) in items.iter().enumerate() {
                    out.push_str(&"  ".repeat(indent + 1));
                    json_escape_str(k, out);
                    out.push_str(": ");
                    v.write(out, indent + 1);
                    if i + 1 < items.len() {
                        out.push(',');
                    }
                    out.push('\n');
                }
                out.push_str(&"  ".repeat(indent));
                out.push('}');
            }
        }
    }
}

fn json_escape_str(s: &str, out: &mut String) {
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\u{08}' => out.push_str("\\b"),
            '\u{0c}' => out.push_str("\\f"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
}
