/// Parse a `=value` default
fn parse_default(s: &str) -> Option<(DefaultValue, &str)> {
    // s starts after '='
    let mut chars = s.chars();
    let first = chars.next()?;
    if first == '"' || first == '\'' {
        let rest = &s[1..];
        let end = rest.find(first)?;
        let value = &rest[..end];
        return Some((DefaultValue::Value(value.to_string()), &rest[end + 1..]));
    }
    if first == '`' {
        let rest = &s[1..];
        if let Some(end) = rest.find('`') {
            let name = &rest[..end];
            let after = &rest[end + 1..];
            if default_fn_ok(name) && (after.is_empty() || after.starts_with(char::is_whitespace)) {
                return Some((DefaultValue::Fn(name.to_string()), after));
            }
        }
    }
    let end = s.find(char::is_whitespace).unwrap_or(s.len());
    if end == 0 {
        return None;
    }
    Some((DefaultValue::Value(s[..end].to_string()), &s[end..]))
}

/// Parse `[...]` choices. s starts with '['
fn parse_choices(s: &str) -> Option<(ChoiceValue, Option<DefaultValue>, &str)> {
    let rest = &s[1..];
    let end = rest.find(']')?;
    let inner = &rest[..end];
    let after = &rest[end + 1..];
    if inner.starts_with('`') && inner.ends_with('`') && inner.len() >= 2 {
        let name = &inner[1..inner.len() - 1];
        if default_fn_ok(name) {
            return Some((ChoiceValue::Fn(name.to_string(), true), None, after));
        }
        return None;
    }
    if inner.starts_with("?`") && inner.ends_with('`') && inner.len() >= 3 {
        let name = &inner[2..inner.len() - 1];
        if default_fn_ok(name) {
            return Some((ChoiceValue::Fn(name.to_string(), false), None, after));
        }
        return None;
    }
    if inner.contains('`') {
        return None;
    }
    let (inner, has_default) = if let Some(v) = inner.strip_prefix('=') {
        (v, true)
    } else {
        (inner, false)
    };
    let values: Vec<String> = inner.split('|').map(|v| v.to_string()).collect();
    let default = if has_default {
        Some(DefaultValue::Value(values[0].clone()))
    } else {
        None
    };
    Some((ChoiceValue::Values(values), default, after))
}

/// Parse modifiers after the name. Returns modifiers and the remaining string,
/// which must be empty or start with whitespace.
fn parse_modifiers(s: &str, allow: &[char]) -> Option<(Modifiers, &str)> {
    let mut m = Modifiers::default();
    let mut rest = s;
    if allow.contains(&'-') && rest.starts_with('-') {
        m.prefixed = true;
        rest = &rest[1..];
    }
    if allow.contains(&':') && rest.starts_with(':') {
        m.assigned = true;
        rest = &rest[1..];
    }
    let mut has_mod = false;
    if let Some(c) = rest.chars().next() {
        match c {
            '!' if allow.contains(&'!') => {
                m.required = true;
                rest = &rest[1..];
                has_mod = true;
            }
            '*' if allow.contains(&'*') => {
                m.multiple = true;
                rest = &rest[1..];
                has_mod = true;
                if let Some(d) = rest.chars().next() {
                    if is_delimiter_char(d) && allow.contains(&',') {
                        m.delimiter = Some(d);
                        rest = &rest[d.len_utf8()..];
                    }
                }
            }
            '+' if allow.contains(&'+') => {
                m.multiple = true;
                m.required = true;
                rest = &rest[1..];
                has_mod = true;
                if let Some(d) = rest.chars().next() {
                    if is_delimiter_char(d) && allow.contains(&',') {
                        m.delimiter = Some(d);
                        rest = &rest[d.len_utf8()..];
                    }
                }
            }
            '~' if allow.contains(&'~') => {
                m.terminated = true;
                m.multiple = true;
                rest = &rest[1..];
                has_mod = true;
            }
            _ => {}
        }
    }
    if let Some(c) = rest.chars().next() {
        if c == '=' && !has_mod && allow.contains(&'=') {
            let (d, r) = parse_default(&rest[1..])?;
            m.default = Some(d);
            rest = r;
        } else if c == '[' && allow.contains(&'[') {
            let (ch, d, r) = parse_choices(rest)?;
            m.choice = Some(ch);
            if d.is_some() {
                m.default = d;
            }
            rest = r;
        }
    }
    if !(rest.is_empty() || rest.starts_with(char::is_whitespace)) {
        return None;
    }
    Some((m, rest))
}

/// Try parsing `name + modifiers` where name is taken lazily (shortest first).
fn parse_name_and_modifiers<'a>(
    s: &'a str,
    allow: &[char],
    name_ok: &dyn Fn(&str) -> bool,
) -> Option<(String, Modifiers, &'a str)> {
    let chars: Vec<(usize, char)> = s.char_indices().collect();
    let mut end_positions = Vec::new();
    for (i, c) in chars.iter() {
        if !is_name_char(*c) {
            break;
        }
        end_positions.push(*i + c.len_utf8());
    }
    for end in end_positions {
        let name = &s[..end];
        if !name_ok(name) {
            continue;
        }
        if let Some((m, rest)) = parse_modifiers(&s[end..], allow) {
            return Some((name.to_string(), m, rest));
        }
    }
    None
}

fn parse_env_token(s: &str) -> Option<(Option<String>, &str)> {
    // s is trimmed start. returns env (None for $$)
    if let Some(rest) = s.strip_prefix("$$") {
        if rest.is_empty() || rest.starts_with(char::is_whitespace) {
            return Some((None, rest));
        }
        return None;
    }
    if let Some(rest) = s.strip_prefix('$') {
        let first = rest.chars().next()?;
        if first.is_ascii_uppercase() || first == '_' {
            let end = rest
                .find(|c: char| !(c.is_ascii_uppercase() || c.is_ascii_digit() || c == '_'))
                .unwrap_or(rest.len());
            let after = &rest[end..];
            if after.is_empty() || after.starts_with(char::is_whitespace) {
                return Some((Some(rest[..end].to_string()), after));
            }
            return None;
        }
    }
    None
}

/// Parse notations `<A> <B>`; returns notations and remainder
fn parse_notations(s: &str, max: usize) -> Option<(Vec<String>, &str)> {
    let mut notations = Vec::new();
    let mut rest = s;
    loop {
        let t = rest.trim_start();
        if notations.len() >= max || !t.starts_with('<') {
            break;
        }
        let end = match t.find('>') {
            Some(v) => v,
            None => break,
        };
        let after = &t[end + 1..];
        if !(after.is_empty() || after.starts_with(char::is_whitespace)) {
            return None;
        }
        notations.push(t[1..end].to_string());
        rest = after;
    }
    Some((notations, rest))
}

pub enum EnvResult {
    None,
    SelfEnv,
    Named(String),
}

fn parse_tail<'a>(s: &'a str, is_flag: bool, max_notations: usize) -> Option<(EnvResult, Vec<String>, String)> {
    let mut rest = s.trim_start();
    let mut env = EnvResult::None;
    if rest.starts_with('$') {
        if let Some((e, r)) = parse_env_token(rest) {
            env = match e {
                None => EnvResult::SelfEnv,
                Some(v) => EnvResult::Named(v),
            };
            rest = r.trim_start();
        } else if rest.starts_with("$$") || rest[1..].starts_with(|c: char| c.is_ascii_uppercase() || c == '_') {
            return None;
        }
    }
    let notations = if is_flag {
        Vec::new()
    } else {
        let (n, r) = parse_notations(rest, max_notations)?;
        rest = r;
        n
    };
    Some((env, notations, rest.trim().to_string()))
}

fn is_short_like(tok: &str) -> bool {
    let chars: Vec<char> = tok.chars().collect();
    chars.len() == 2 && (chars[0] == '-' || chars[0] == '+') && is_name_char(chars[1])
}

fn split_prefix(tok: &str) -> Option<(&str, &str)> {
    if let Some(r) = tok.strip_prefix("--") {
        Some(("--", r))
    } else if let Some(r) = tok.strip_prefix('-') {
        Some(("-", r))
    } else if let Some(r) = tok.strip_prefix('+') {
        Some(("+", r))
    } else {
        None
    }
}

fn parse_long_token(tok: &str, is_flag: bool) -> Option<(String, String, Modifiers, &str)> {
    // returns (prefix, name, modifiers, rest)
    let (prefix, rest) = split_prefix(tok)?;
    if rest.is_empty() || rest.starts_with('-') {
        return None;
    }
    let allow: &[char] = if is_flag {
        &['-', '*']
    } else {
        &['-', ':', '!', '*', '+', ',', '~', '=', '[']
    };
    let (name, m, r) = parse_name_and_modifiers(rest, allow, &|n: &str| !n.is_empty())?;
    Some((prefix.to_string(), name, m, r))
}

pub fn parse_flag_option(text: &str, is_flag: bool, line: usize) -> Option<FlagOptionParam> {
    let s = text.trim_start();
    let tok1_end = s.find(char::is_whitespace).unwrap_or(s.len());
    let tok1 = &s[..tok1_end];
    let after1 = &s[tok1_end..];
    let mut parsed: Option<(Option<String>, String, String, Modifiers, &str)> = None;
    if is_short_like(tok1) {
        let t = after1.trim_start();
        if t.starts_with('-') || t.starts_with('+') {
            let tok2_end = t.find(char::is_whitespace).unwrap_or(t.len());
            let tok2 = &t[..tok2_end];
            if let Some((prefix, name, m, r)) = parse_long_token(tok2, is_flag) {
                let rest = if r.is_empty() { &t[tok2_end..] } else { r };
                let _ = rest;
                parsed = Some((Some(tok1.to_string()), prefix, name, m, &t[tok2_end..]));
            }
        }
    }
    if parsed.is_none() {
        let (prefix, name, m, _r) = parse_long_token(tok1, is_flag)?;
        parsed = Some((None, prefix, name, m, after1));
    }
    let (short, prefix, name, m, rest) = parsed?;
    let (env, notations, describe) = parse_tail(rest, is_flag, usize::MAX)?;
    let long_name = format!("{prefix}{name}");
    let id = if prefix == "+" {
        format!("plus_{name}")
    } else {
        name.clone()
    };
    let env = match env {
        EnvResult::None => None,
        EnvResult::SelfEnv => Some(to_cobol_case(&id).replace('-', "_")),
        EnvResult::Named(v) => Some(v),
    };
    let mut param = FlagOptionParam {
        id,
        long_name,
        short_name: short,
        describe,
        flag: is_flag,
        notations: Vec::new(),
        required: m.required && m.default.is_none(),
        multiple_values: false,
        multiple_occurs: m.multiple,
        num_args: (0, 0),
        delimiter: m.delimiter,
        terminated: m.terminated,
        prefixed: m.prefixed,
        assigned: m.assigned,
        default: m.default,
        choice: m.choice,
        env,
        inherited: false,
        line,
    };
    if is_flag {
        param.multiple_values = param.multiple_occurs;
        param.required = false;
        param.terminated = false;
    } else {
        let mut notations = if notations.is_empty() {
            vec![to_cobol_case(&name)]
        } else {
            notations
        };
        if m.terminated {
            let last = notations.last_mut().unwrap();
            last.push('~');
            param.multiple_occurs = false;
        }
        let n = notations.len();
        let (min, max) = if m.terminated {
            (n, MAX_ARGS)
        } else {
            let last = notations.last().unwrap();
            if last.ends_with('?') {
                (n - 1, n)
            } else if last.ends_with('*') {
                (n - 1, MAX_ARGS)
            } else if last.ends_with('+') {
                (n, MAX_ARGS)
            } else {
                (n, n)
            }
        };
        param.num_args = (min, max);
        param.notations = notations;
        param.multiple_values = param.multiple_occurs || max > 1;
    }
    Some(param)
}

pub fn parse_positional(text: &str, line: usize) -> Option<PositionalParam> {
    let s = text.trim_start();
    if s.is_empty() {
        return None;
    }
    let first = s.chars().next()?;
    if !(is_name_char(first)) {
        return None;
    }
    let allow: &[char] = &['!', '*', '+', ',', '~', '=', '['];
    let (name, m, rest) = parse_name_and_modifiers(s, allow, &|n: &str| !n.is_empty())?;
    let (env, notations, describe) = parse_tail(rest, false, 1)?;
    let env = match env {
        EnvResult::None => None,
        EnvResult::SelfEnv => Some(to_cobol_case(&name).replace('-', "_")),
        EnvResult::Named(v) => Some(v),
    };
    let notation = notations
        .into_iter()
        .next()
        .unwrap_or_else(|| to_cobol_case(&name));
    Some(PositionalParam {
        id: name,
        describe,
        notation,
        required: m.required && m.default.is_none(),
        multiple: m.multiple,
        delimiter: m.delimiter,
        terminated: m.terminated,
        default: m.default,
        choice: m.choice,
        env,
        line,
    })
}

pub fn parse_env(text: &str, line: usize) -> Option<EnvParam> {
    let s = text.trim_start();
    if s.is_empty() {
        return None;
    }
    let first = s.chars().next()?;
    if !(first.is_ascii_alphanumeric() || first == '_') {
        return None;
    }
    let allow: &[char] = &['!', '=', '['];
    let (name, m, rest) = parse_name_and_modifiers(s, allow, &|n: &str| {
        n.chars().all(|c| c.is_ascii_alphanumeric() || c == '_')
    })?;
    Some(EnvParam {
        id: name,
        describe: rest.trim().to_string(),
        required: m.required && m.default.is_none(),
        default: m.default,
        choice: m.choice,
        inherited: false,
        line,
    })
}

pub fn parse_symbol(text: &str) -> Option<SymbolParam> {
    let s = text.trim();
    let ch = s.chars().next()?;
    if ch != '+' && ch != '@' {
        return None;
    }
    let rest = &s[1..];
    let end = rest
        .find(|c: char| !(c.is_ascii_alphanumeric() || c == '_' || c == '-'))
        .unwrap_or(rest.len());
    let name = &rest[..end];
    if name.is_empty() {
        return None;
    }
    let after = &rest[end..];
    let choice = if after.is_empty() {
        None
    } else if after.starts_with("[`") && after.ends_with("`]") && after.len() > 4 {
        let f = &after[2..after.len() - 2];
        if !default_fn_ok(f) {
            return None;
        }
        Some(ChoiceValue::Fn(f.to_string(), true))
    } else {
        return None;
    };
    Some(SymbolParam {
        ch,
        name: name.to_string(),
        choice,
    })
}

// ---------------- rendering helpers -----------------

impl FlagOptionParam {
    pub fn var_name(&self) -> String {
        format!("argc_{}", argc_var_name(&self.id))
    }

    pub fn is_help(&self) -> bool {
        self.id == "help"
    }

    pub fn is_version(&self) -> bool {
        self.id == "version"
    }

    pub fn list_names(&self) -> Vec<String> {
        let mut v = vec![self.long_name.clone()];
        if let Some(s) = &self.short_name {
            v.push(s.clone());
        }
        v
    }

    pub fn prefix_char(&self) -> char {
        self.long_name.chars().next().unwrap_or('-')
    }

    /// e.g. `<FOO>`, `[FOO]...`, `<A> <B>`
    pub fn render_notations(&self) -> String {
        if self.flag {
            return String::new();
        }
        if self.notations.len() == 1 {
            let n = &self.notations[0];
            if self.multiple_values && self.num_args.1 <= 1 {
                // multi occurs
                if self.required {
                    return format!("<{n}>...");
                }
                return format!("[{n}]...");
            }
            if self.multiple_values && !self.terminated && self.num_args.1 > 1 && !n.ends_with('*') && !n.ends_with('+') {
                // e.g. multiple occurs? fallthrough
            }
            return format!("<{n}>");
        }
        self.notations
            .iter()
            .map(|n| format!("<{n}>"))
            .collect::<Vec<String>>()
            .join(" ")
    }

    /// e.g. `--foo <FOO>`, `--follow=<FOLLOW>`
    pub fn render_long_with_notations(&self) -> String {
        self.render_name_with_notations(&self.long_name)
    }

    pub fn render_name_with_notations(&self, name: &str) -> String {
        if self.flag {
            return name.to_string();
        }
        let n = self.render_notations();
        if self.assigned {
            format!("{name}={n}")
        } else {
            format!("{name} {n}")
        }
    }

    pub fn render_first_notation(&self) -> String {
        self.notations.first().cloned().unwrap_or_default()
    }

    /// body for help: short + long + notations, with alignment handled by caller
    pub fn render_body(&self, all_double_dash: bool) -> String {
        let mut out = String::new();
        let single_char = self.long_name.chars().count() == 2;
        match &self.short_name {
            Some(s) => {
                out.push_str(s);
                out.push_str(", ");
            }
            None => {
                if !single_char {
                    out.push_str("    ");
                }
            }
        }
        if single_char && self.short_name.is_none() {
            out.push_str(&self.long_name);
        } else if all_double_dash {
            out.push_str(&self.long_name);
        } else {
            let (prefix, name) = split_prefix(&self.long_name).unwrap_or(("", &self.long_name));
            out.push_str(&format!("{prefix:>2}{name}"));
        }
        if !self.flag {
            let n = self.render_notations();
            if self.assigned {
                out.push('=');
            } else {
                out.push(' ');
            }
            out.push_str(&n);
        }
        if self.multiple_occurs && self.flag {
            out.push_str("...");
        }
        out
    }

    pub fn to_json(&self) -> Json {
        Json::Obj(vec![
            ("id".into(), Json::str(&self.id)),
            ("long_name".into(), Json::str(&self.long_name)),
            ("short_name".into(), Json::opt_str(&self.short_name)),
            ("describe".into(), Json::str(&self.describe)),
            ("flag".into(), Json::Bool(self.flag)),
            ("notations".into(), Json::strs(&self.notations)),
            ("required".into(), Json::Bool(self.required)),
            ("multiple_values".into(), Json::Bool(self.multiple_values)),
            ("multiple_occurs".into(), Json::Bool(self.multiple_occurs)),
            (
                "num_args".into(),
                Json::Arr(vec![
                    Json::Num(self.num_args.0 as i64),
                    Json::Num(self.num_args.1 as i64),
                ]),
            ),
            (
                "delimiter".into(),
                match self.delimiter {
                    Some(c) => Json::Str(c.to_string()),
                    None => Json::Null,
                },
            ),
            ("terminated".into(), Json::Bool(self.terminated)),
            ("prefixed".into(), Json::Bool(self.prefixed)),
            ("assigned".into(), Json::Bool(self.assigned)),
            (
                "default".into(),
                self.default.as_ref().map(|v| v.to_json()).unwrap_or(Json::Null),
            ),
            (
                "choice".into(),
                self.choice.as_ref().map(|v| v.to_json()).unwrap_or(Json::Null),
            ),
            ("env".into(), Json::opt_str(&self.env)),
            ("inherited".into(), Json::Bool(self.inherited)),
        ])
    }
}

impl PositionalParam {
    pub fn var_name(&self) -> String {
        format!("argc_{}", argc_var_name(&self.id))
    }

    /// `<VAL>`, `[VAL]`, `<VAL>...`, `[VAL]...`
    pub fn render_notation(&self) -> String {
        let n = &self.notation;
        let base = if self.required {
            format!("<{n}>")
        } else {
            format!("[{n}]")
        };
        if self.multiple {
            format!("{base}...")
        } else {
            base
        }
    }

    pub fn to_json(&self) -> Json {
        Json::Obj(vec![
            ("id".into(), Json::str(&self.id)),
            ("describe".into(), Json::str(&self.describe)),
            ("notation".into(), Json::str(&self.notation)),
            ("required".into(), Json::Bool(self.required)),
            ("multiple".into(), Json::Bool(self.multiple)),
            (
                "delimiter".into(),
                match self.delimiter {
                    Some(c) => Json::Str(c.to_string()),
                    None => Json::Null,
                },
            ),
            ("terminated".into(), Json::Bool(self.terminated)),
            (
                "default".into(),
                self.default.as_ref().map(|v| v.to_json()).unwrap_or(Json::Null),
            ),
            (
                "choice".into(),
                self.choice.as_ref().map(|v| v.to_json()).unwrap_or(Json::Null),
            ),
            ("env".into(), Json::opt_str(&self.env)),
        ])
    }
}

impl EnvParam {
    pub fn render_name(&self) -> String {
        if self.required {
            format!("{}*", self.id)
        } else {
            self.id.clone()
        }
    }

    pub fn to_json(&self) -> Json {
        Json::Obj(vec![
            ("id".into(), Json::str(&self.id)),
            ("describe".into(), Json::str(&self.describe)),
            ("required".into(), Json::Bool(self.required)),
            (
                "default".into(),
                self.default.as_ref().map(|v| v.to_json()).unwrap_or(Json::Null),
            ),
            (
                "choice".into(),
                self.choice.as_ref().map(|v| v.to_json()).unwrap_or(Json::Null),
            ),
            ("inherited".into(), Json::Bool(self.inherited)),
        ])
    }
}

/// Render the trailing info `[possible values: ..] [default: ..] [env: ..]`
pub fn render_extra_info(
    describe: &str,
    choice: &Option<ChoiceValue>,
    default: &Option<DefaultValue>,
    env: &Option<String>,
) -> Vec<String> {
    let mut parts = Vec::new();
    let mut skip = false;
    if let Some(ChoiceValue::Values(values)) = choice {
        if values.iter().all(|v| describe.contains(v.as_str())) {
            skip = true;
        } else {
            parts.push(format!("[possible values: {}]", values.join(", ")));
        }
    }
    if !skip {
        if let Some(DefaultValue::Value(v)) = default {
            parts.push(format!("[default: {v}]"));
        }
    }
    if let Some(e) = env {
        parts.push(format!("[env: {e}]"));
    }
    parts
}
