use crate::param::{parse_env, parse_flag_option, parse_positional, EnvParam, FlagOptionParam, PositionalParam};

#[derive(Debug, Clone)]
pub enum EventData {
    Describe(String),
    Version(String),
    Meta(String, Option<String>),
    Cmd(String),
    Aliases(Vec<String>),
    FlagOption(FlagOptionParam),
    Positional(PositionalParam),
    Env(EnvParam),
    Func(String),
    Unknown(String),
}

#[derive(Debug, Clone)]
pub struct Event {
    pub line: usize,
    pub data: EventData,
}

pub fn parse_script(source: &str) -> Result<Vec<Event>, String> {
    let mut events: Vec<Event> = Vec::new();
    // index into events of the last describable event, for continuation lines
    let mut pending_describe: Option<usize> = None;
    for (idx, raw_line) in source.lines().enumerate() {
        let line_no = idx + 1;
        if raw_line.starts_with('#') {
            // strip leading '#'s
            let stripped = raw_line.trim_start_matches('#');
            let content = stripped.trim_start();
            if content.starts_with('@') {
                let tag_text = &content[1..];
                // determine tag name
                let name_end = tag_text
                    .find(|c: char| c.is_whitespace())
                    .unwrap_or(tag_text.len());
                let word = &tag_text[..name_end];
                let rest_after_word = &tag_text[name_end..];
                // param tags are matched by prefix
                let param_tags = ["option", "flag", "arg", "env"];
                let mut matched = false;
                for t in param_tags {
                    if let Some(after) = tag_text.strip_prefix(t) {
                        matched = true;
                        let data = match t {
                            "option" | "flag" => match parse_flag_option(after, t == "flag", line_no) {
                                Some(p) => EventData::FlagOption(p),
                                None => return Err(format!("syntax error at line {line_no}")),
                            },
                            "arg" => match parse_positional(after, line_no) {
                                Some(p) => EventData::Positional(p),
                                None => return Err(format!("syntax error at line {line_no}")),
                            },
                            _ => match parse_env(after, line_no) {
                                Some(p) => EventData::Env(p),
                                None => return Err(format!("syntax error at line {line_no}")),
                            },
                        };
                        events.push(Event { line: line_no, data });
                        pending_describe = Some(events.len() - 1);
                        break;
                    }
                }
                if matched {
                    continue;
                }
                let value = rest_after_word.trim();
                match word {
                    "describe" => {
                        events.push(Event {
                            line: line_no,
                            data: EventData::Describe(value.to_string()),
                        });
                        pending_describe = Some(events.len() - 1);
                    }
                    "cmd" => {
                        events.push(Event {
                            line: line_no,
                            data: EventData::Cmd(value.to_string()),
                        });
                        pending_describe = Some(events.len() - 1);
                    }
                    "version" => {
                        events.push(Event {
                            line: line_no,
                            data: EventData::Version(value.to_string()),
                        });
                        pending_describe = None;
                    }
                    "alias" => {
                        if value.is_empty() {
                            events.push(Event {
                                line: line_no,
                                data: EventData::Unknown("alias".to_string()),
                            });
                        } else {
                            let aliases: Vec<String> = value
                                .split(',')
                                .map(|v| v.trim().to_string())
                                .filter(|v| !v.is_empty())
                                .collect();
                            events.push(Event {
                                line: line_no,
                                data: EventData::Aliases(aliases),
                            });
                        }
                        pending_describe = None;
                    }
                    "meta" => {
                        if value.is_empty() {
                            events.push(Event {
                                line: line_no,
                                data: EventData::Unknown("meta".to_string()),
                            });
                        } else {
                            let (k, v) = match value.find(char::is_whitespace) {
                                Some(i) => (
                                    value[..i].to_string(),
                                    Some(value[i..].trim().to_string()),
                                ),
                                None => (value.to_string(), None),
                            };
                            events.push(Event {
                                line: line_no,
                                data: EventData::Meta(k, v),
                            });
                        }
                        pending_describe = None;
                    }
                    "" => {
                        // `# @` or `# @ xxx`: ignored, ends describe block
                        pending_describe = None;
                    }
                    _ => {
                        events.push(Event {
                            line: line_no,
                            data: EventData::Unknown(word.to_string()),
                        });
                        pending_describe = None;
                    }
                }
            } else if let Some(i) = pending_describe {
                // continuation line
                let mut text = stripped;
                if text.starts_with(' ') || text.starts_with('\t') {
                    text = &text[1..];
                }
                let text = text.trim_end();
                let target = &mut events[i].data;
                let desc: &mut String = match target {
                    EventData::Describe(d) => d,
                    EventData::Cmd(d) => d,
                    EventData::FlagOption(p) => &mut p.describe,
                    EventData::Positional(p) => &mut p.describe,
                    EventData::Env(p) => &mut p.describe,
                    _ => continue,
                };
                desc.push('\n');
                desc.push_str(text);
            }
        } else {
            pending_describe = None;
            if let Some(name) = parse_fn_name(raw_line) {
                events.push(Event {
                    line: line_no,
                    data: EventData::Func(name),
                });
            }
        }
    }
    // trim describes
    for ev in events.iter_mut() {
        match &mut ev.data {
            EventData::Describe(d) | EventData::Cmd(d) => *d = d.trim().to_string(),
            EventData::FlagOption(p) => p.describe = p.describe.trim().to_string(),
            EventData::Positional(p) => p.describe = p.describe.trim().to_string(),
            EventData::Env(p) => p.describe = p.describe.trim().to_string(),
            _ => {}
        }
    }
    Ok(events)
}

fn is_fn_char(c: char) -> bool {
    c.is_ascii_alphanumeric() || matches!(c, '_' | '-' | '.' | ':')
}

fn parse_fn_name(line: &str) -> Option<String> {
    let line = line.trim_end();
    if let Some(rest) = line.strip_prefix("function ") {
        let rest = rest.trim_start();
        let end = rest.find(|c: char| !is_fn_char(c)).unwrap_or(rest.len());
        let name = &rest[..end];
        if name.is_empty() {
            return None;
        }
        let after = rest[end..].trim_start();
        if after.is_empty() || after.starts_with('{') || after.starts_with("()") {
            return Some(name.to_string());
        }
        return None;
    }
    let end = line.find(|c: char| !is_fn_char(c)).unwrap_or(line.len());
    let name = &line[..end];
    if name.is_empty() {
        return None;
    }
    let after = line[end..].trim_start();
    if let Some(after) = after.strip_prefix("()") {
        let after = after.trim_start();
        if after.is_empty() || after.starts_with('{') {
            return Some(name.to_string());
        }
    }
    None
}
