{"command":"cat > /workspace/src/command.rs <<'EOF'
use crate::param::{
    parse_symbol, render_extra_info, ChoiceValue, DefaultValue, EnvParam, FlagOptionParam,
    PositionalParam, SymbolParam,
};
use crate::parser::{parse_script, EventData};
use crate::utils::{wrap_text_opt, Json};

#[derive(Debug, Clone, Default)]
pub struct Command {
    pub name: Option<String>,
    pub fn_name: Option<String>,
    pub describe: String,
    pub version: Option<String>,
    pub author: Option<String>,
    pub aliases: Vec<String>,
    pub flag_options: Vec<FlagOptionParam>,
    pub positionals: Vec<PositionalParam>,
    pub envs: Vec<EnvParam>,
    pub subcommands: Vec<Command>,
    pub metadata: Vec<(String, Option<String>)>,
    pub symbols: Vec<SymbolParam>,
    pub require_tools: Vec<String>,
    pub default_subcommand: bool,
    pub inherit_flag_options: bool,
    pub combine_shorts: bool,
    pub dotenv: Option<String>,
    pub man_section: Option<String>,
    pub line: usize,
    pub alias_line: usize,
    pub default_subcommand_line: usize,
    pub paths: Vec<String>,
    pub root_name: String,
    pub exist_main_fn: bool,
    pub exist_hook_before: bool,
    pub exist_hook_after: bool,
    pub is_root: bool,
}

pub struct ParsedCommand {
    pub root: Command,
}

fn script_name_of(path: &str) -> String {
    let p = std::path::Path::new(path);
    let file_name = p
        .file_name()
        .map(|v| v.to_string_lossy().to_string())
        .unwrap_or_default();
    if let Some(stem) = file_name.strip_suffix(".sh") {
        stem.to_string()
    } else {
        file_name
    }
}

impl Command {
    pub fn new(source: &str, script_path: &str) -> Result<Command, String> {
        let root_name = script_name_of(script_path);
        let events = parse_script(source)?;
        let mut root = Command {
            is_root: true,
            root_name: root_name.clone(),
            ..Default::default()
        };
        let mut pending: Option<Command> = None;
        let mut root_done = false; // once a subcommand function has been seen
        let mut fn_names: Vec<String> = Vec::new();
        let mut used_fns: Vec<(String, usize)> = Vec::new(); // fn names referenced by default/choice
        for ev in events.iter() {
            let line = ev.line;
            macro_rules! target {
                () => {
                    match pending.as_mut() {
                        Some(c) => c,
                        None => &mut root,
                    }
                };
            }
            match &ev.data {
                EventData::Func(name) => {
                    fn_names.push(name.clone());
                    if let Some(mut cmd) = pending.take() {
                        cmd.fn_name = Some(name.clone());
                        cmd.line = line;
                        let parts: Vec<&str> = name.split("::").collect();
                        let short = parts.last().unwrap().to_string();
                        cmd.name = Some(short.clone());
                        if short.contains('_') {
                            cmd.aliases.insert(0, short.replace('_', "-"));
                        }
                        // find parent
                        let parent: &mut Command = if parts.len() > 1 {
                            match root.find_subcommand_by_fn_path(&parts[..parts.len() - 1]) {
                                Some(p) => p,
                                None => return Err(format!("{name}(line {line}) lack of parent command")),
                            }
                        } else {
                            &mut root
                        };
                        // conflicts
                        for existing in parent.subcommands.iter() {
                            if existing.name.as_deref() == Some(short.as_str()) {
                                return Err(format!(
                                    "{name}(line {line}) conflicts with cmd or alias at line {}",
                                    existing.line
                                ));
                            }
                            if existing.aliases.iter().any(|a| a == &short) {
                                return Err(format!(
                                    "{name}(line {line}) conflicts with cmd or alias at line {}",
                                    existing.alias_line
                                ));
                            }
                            for a in cmd.aliases.iter() {
                                if existing.name.as_deref() == Some(a.as_str()) {
                                    return Err(format!(
                                        "{name}(line {line}) conflicts with cmd or alias at line {}",
                                        existing.line
                                    ));
                                }
                            }
                        }
                        parent.subcommands.push(cmd);
                        root_done = true;
                    } else {
                        match name.as_str() {
                            "main" => root.exist_main_fn = true,
                            "_argc_before" => root.exist_hook_before = true,
                            "_argc_after" => root.exist_hook_after = true,
                            _ => {}
                        }
                    }
                }
                EventData::Cmd(describe) => {
                    if let Some(p) = pending.as_ref() {
                        return Err(format!("@cmd(line {}) missing function?", p.line));
                    }
                    let cmd = Command {
                        describe: describe.clone(),
                        line,
                        root_name: root_name.clone(),
                        ..Default::default()
                    };
                    pending = Some(cmd);
                }
                EventData::Unknown(tag) => {
                    return Err(format!("@{tag}(line {line}) is unknown tag"));
                }
                _ => {
                    if pending.is_none() && root_done {
                        let tag = match &ev.data {
                            EventData::Describe(_) => "describe",
                            EventData::Version(_) => "version",
                            EventData::Meta(_, _) => "meta",
                            EventData::Aliases(_) => "alias",
                            EventData::FlagOption(p) => {
                                if p.flag {
                                    "flag"
                                } else {
                                    "option"
                                }
                            }
                            EventData::Positional(_) => "arg",
                            EventData::Env(_) => "env",
                            _ => "",
                        };
                        return Err(format!(
                            "@{tag}(line {line}) shouldn't be here, @cmd is missing?"
                        ));
                    }
                    match &ev.data {
                        EventData::Describe(d) => {
                            target!().describe = d.clone();
                        }
                        EventData::Version(v) => {
                            target!().version = Some(v.clone());
                        }
                        EventData::Aliases(aliases) => {
                            // conflict check against root subcommands
                            for a in aliases.iter() {
                                for existing in root.subcommands.iter() {
                                    if existing.name.as_deref() == Some(a.as_str()) {
                                        return Err(format!(
                                            "@alias(line {line}) conflicts with cmd or alias at line {}",
                                            existing.line
                                        ));
                                    }
                                    if existing.aliases.iter().any(|x| x == a) {
                                        return Err(format!(
                                            "@alias(line {line}) conflicts with cmd or alias at line {}",
                                            existing.alias_line
                                        ));
                                    }
                                }
                            }
                            let t = target!();
                            t.aliases = aliases.clone();
                            t.alias_line = line;
                        }
                        EventData::Meta(key, value) => {
                            let is_root = pending.is_none();
                            let t = target!();
                            match key.as_str() {
                                "version" => match value {
                                    Some(v) => t.version = Some(v.clone()),
                                    None => return Err(format!("@meta(line {line}) invalid version value")),
                                },
                                "author" => {
                                    t.author = value.clone();
                                }
                                "dotenv" => {
                                    if is_root {
                                        t.dotenv = Some(value.clone().unwrap_or_else(|| ".env".to_string()));
                                    }
                                }
                                "default-subcommand" => {
                                    t.default_subcommand = true;
                                    t.default_subcommand_line = line;
                                }
                                "inherit-flag-options" => {
                                    t.inherit_flag_options = true;
                                }
                                "combine-shorts" => {
                                    if is_root {
                                        t.combine_shorts = true;
                                    }
                                }
                                "symbol" => {
                                    let sym = value.as_deref().and_then(parse_symbol);
                                    match sym {
                                        Some(s) => t.symbols.push(s),
                                        None => return Err(format!("@meta(line {line}) invalid symbol value")),
                                    }
                                }
                                "require-tools" => {
                                    if let Some(v) = value {
                                        t.require_tools = v
                                            .split(',')
                                            .map(|x| x.trim().to_string())
                                            .filter(|x| !x.is_empty())
                                            .collect();
                                    }
                                }
                                "man-section" => {
                                    t.man_section = value.clone();
                                }
                                _ => {}
                            }
                            if let Some(pos) = t.metadata.iter().position(|(k, _)| k == key) {
                                t.metadata[pos].1 = value.clone();
                            } else {
                                t.metadata.push((key.clone(), value.clone()));
                            }
                        }
                        EventData::FlagOption(p) => {
                            if let Some(d) = &p.default {
                                if let DefaultValue::Fn(f) = d {
                                    used_fns.push((f.clone(), line));
                                }
                            }
                            if let Some(ChoiceValue::Fn(f, _)) = &p.choice {
                                used_fns.push((f.clone(), line));
                            }
                            let t = target!();
                            let tag = if p.flag { "flag" } else { "option" };
                            for existing in t.flag_options.iter() {
                                for n in p.list_names() {
                                    if existing.list_names().contains(&n) {
                                        return Err(format!(
                                            "@{tag}(line {line}) has '{n}' already exists at line {}",
                                            existing.line
                                        ));
                                    }
                                }
                            }
                            t.flag_options.push(p.clone());
                        }
                        EventData::Positional(p) => {
                            if let Some(DefaultValue::Fn(f)) = &p.default {
                                used_fns.push((f.clone(), line));
                            }
                            if let Some(ChoiceValue::Fn(f, _)) = &p.choice {
                                used_fns.push((f.clone(), line));
                            }
                            let t = target!();
                            for existing in t.positionals.iter() {
                                if existing.id == p.id {
                                    return Err(format!(
                                        "@arg(line {line}) has '{}' already exists at line {}",
                                        p.id, existing.line
                                    ));
                                }
                            }
                            t.positionals.push(p.clone());
                        }
                        EventData::Env(p) => {
                            if let Some(DefaultValue::Fn(f)) = &p.default {
                                used_fns.push((f.clone(), line));
                            }
                            if let Some(ChoiceValue::Fn(f, _)) = &p.choice {
                                used_fns.push((f.clone(), line));
                            }
                            let t = target!();
                            for existing in t.envs.iter() {
                                if existing.id == p.id {
                                    return Err(format!(
                                        "@env(line {line}) has '{}' already exists at line {}",
                                        p.id, existing.line
                                    ));
                                }
                            }
                            t.envs.push(p.clone());
                        }
                        _ => {}
                    }
                }
            }
        }
        if let Some(cmd) = pending.take() {
            root.subcommands.push(cmd);
        }
        for (f, line) in used_fns.iter() {
            if !fn_names.contains(f) {
                return Err(format!("{f}(line {line}) is missing"));
            }
        }
        // default subcommand conflicts
        root.check_default_subcommands()?;
        root.finalize(&[], None, None);
        Ok(root)
    }

    fn check_default_subcommands(&self) -> Result<(), String> {
        let mut found: Option<usize> = None;
        for sub in self.subcommands.iter() {
            if sub.default_subcommand {
                if let Some(prev) = found {
                    return Err(format!(
                        "@meta(line {}) conflicts with {}",
                        sub.default_subcommand_line, prev
                    ));
                }
                found = Some(sub.default_subcommand_line);
            }
            sub.check_default_subcommands()?;
        }
        Ok(())
    }

    fn find_subcommand_by_fn_path(&mut self, parts: &[&str]) -> Option<&mut Command> {
        let mut cur = self;
        for p in parts {
            let idx = cur
                .subcommands
                .iter()
                .position(|c| c.name.as_deref() == Some(*p))?;
            cur = &mut cur.subcommands[idx];
        }
        Some(cur)
    }

    /// finalize: add help/version flags, inherit, compute paths
    fn finalize(
        &mut self,
        parent_paths: &[String],
        inherited_flags: Option<&Vec<FlagOptionParam>>,
        inherited_envs: Option<&Vec<EnvParam>>,
    ) {
        let mut paths = parent_paths.to_vec();
        if self.is_root {
            paths.push(self.root_name.clone());
        } else {
            paths.push(self.name.clone().unwrap_or_default());
        }
        self.paths = paths.clone();

        let has_describe = self.flag_options.iter().any(|f| !f.describe.is_empty());
        let all_double = self.flag_options.iter().all(|f| f.long_name.starts_with("--"));
        let make = |id: &str, short: &str, desc: &str| {
            let long = if all_double {
                format!("--{id}")
            } else {
                format!("-{id}")
            };
            let short_taken = self
                .flag_options
                .iter()
                .any(|f| f.list_names().iter().any(|n| n == short));
            FlagOptionParam {
                id: id.to_string(),
                long_name: long,
                short_name: if short_taken { None } else { Some(short.to_string()) },
                describe: if has_describe { desc.to_string() } else { String::new() },
                flag: true,
                notations: vec![],
                required: false,
                multiple_values: false,
                multiple_occurs: false,
                num_args: (0, 0),
                delimiter: None,
                terminated: false,
                prefixed: false,
                assigned: false,
                default: None,
                choice: None,
                env: None,
                inherited: false,
                line: 0,
            }
        };
        if !self.flag_options.iter().any(|f| f.id == "help") {
            let p = make("help", "-h", "Print help");
            self.flag_options.push(p);
        }
        if (self.is_root || self.version.is_some())
            && !self.flag_options.iter().any(|f| f.id == "version")
        {
            let p = make("version", "-V", "Print version");
            self.flag_options.push(p);
        }
        // inherit flag options
        if let Some(flags) = inherited_flags {
            let mut new_flags: Vec<FlagOptionParam> = Vec::new();
            for f in flags.iter() {
                if self.flag_options.iter().any(|x| x.id == f.id) {
                    continue;
                }
                let mut f = f.clone();
                f.inherited = true;
                new_flags.push(f);
            }
            new_flags.extend(self.flag_options.drain(..));
            self.flag_options = new_flags;
        }
        if let Some(envs) = inherited_envs {
            let mut new_envs: Vec<EnvParam> = Vec::new();
            for e in envs.iter() {
                if self.envs.iter().any(|x| x.id == e.id) {
                    continue;
                }
                let mut e = e.clone();
                e.inherited = true;
                new_envs.push(e);
            }
            new_envs.extend(self.envs.drain(..));
            self.envs = new_envs;
        }
        let pass_flags: Option<Vec<FlagOptionParam>> = if self.inherit_flag_options {
            Some(
                self.flag_options
                    .iter()
                    .filter(|f| !f.is_help() && !f.is_version())
                    .cloned()
                    .collect(),
            )
        } else {
            None
        };
        let pass_envs: Option<Vec<EnvParam>> = if self.envs.is_empty() {
            None
        } else {
            Some(self.envs.clone())
        };
        for sub in self.subcommands.iter_mut() {
            sub.root_name = self.root_name.clone();
            sub.finalize(&paths, pass_flags.as_ref(), pass_envs.as_ref());
        }
    }

    pub fn name_str(&self) -> String {
        if self.is_root {
            self.root_name.clone()
        } else {
            match &self.name {
                Some(n) if !n.is_empty() => n.clone(),
                _ => self.root_name.clone(),
            }
        }
    }

    pub fn full_name(&self) -> String {
        self.paths.join("-")
    }

    pub fn cmd_paths_str(&self) -> String {
        self.paths.join(" ")
    }

    pub fn find_subcommand(&self, name: &str) -> Option<&Command> {
        self.subcommands.iter().find(|c| {
            c.name.as_deref().map(|n| !n.is_empty() && n == name).unwrap_or(false)
                || c.aliases.iter().any(|a| a == name)
        })
    }

    pub fn find_default_subcommand(&self) -> Option<&Command> {
        self.subcommands.iter().find(|c| c.default_subcommand)
    }

    pub fn find_flag_option(&self, name: &str) -> Option<&FlagOptionParam> {
        self.flag_options
            .iter()
            .find(|f| f.long_name == name || f.short_name.as_deref() == Some(name))
    }

    pub fn find_flag_option_by_id(&self, id: &str) -> Option<&FlagOptionParam> {
        self.flag_options.iter().find(|f| f.id == id)
    }

    pub fn list_subcommand_names(&self) -> Vec<String> {
        let mut out = Vec::new();
        for c in self.subcommands.iter() {
            if let Some(n) = &c.name {
                if !n.is_empty() {
                    out.push(n.clone());
                }
            }
            out.extend(c.aliases.iter().cloned());
        }
        out
    }

    pub fn flag_option_signs(&self) -> String {
        let mut signs = String::new();
        for f in self.flag_options.iter() {
            for n in f.list_names() {
                if let Some(c) = n.chars().next() {
                    if (c == '-' || c == '+') && !signs.contains(c) {
                        signs.push(c);
                    }
                }
            }
        }
        // order: '-' first then '+'
        let mut out = String::new();
        if signs.contains('-') {
            out.push('-');
        }
        if signs.contains('+') {
            out.push('+');
        }
        out
    }

    pub fn has_user_flag_options(&self) -> bool {
        self.flag_options.iter().any(|f| !f.is_help() && !f.is_version())
    }

    pub fn render_version(&self) -> String {
        format!(
            "{} {}",
            self.full_name(),
            self.version.clone().unwrap_or_else(|| "0.0.0".to_string())
        )
    }

    pub fn describe_head(&self) -> &str {
        self.describe.split('\n').next().unwrap_or("")
    }

    // ---------------- help -----------------

    pub fn render_usage(&self) -> String {
        let mut parts = vec![format!("USAGE: {}", self.cmd_paths_str())];
        if self.flag_options.iter().any(|f| !f.required && !f.is_help() && !f.is_version()) {
            parts.push("[OPTIONS]".to_string());
        }
        for f in self.flag_options.iter().filter(|f| f.required) {
            parts.push(f.render_long_with_notations());
        }
        for p in self.positionals.iter() {
            parts.push(p.render_notation());
        }
        if !self.subcommands.is_empty() {
            parts.push("<COMMAND>".to_string());
        }
        parts.join(" ")
    }

    pub fn render_help(&self, term_width: Option<usize>) -> String {
        let mut sections: Vec<String> = Vec::new();
        if !self.describe.is_empty() {
            let lines = wrap_text_opt(&self.describe, term_width);
            sections.push(lines.join("\n"));
        }
        sections.push(self.render_usage());
        if !self.positionals.is_empty() {
            let items: Vec<(String, String, Vec<String>)> = self
                .positionals
                .iter()
                .map(|p| {
                    (
                        p.render_notation(),
                        p.describe.clone(),
                        render_extra_info(&p.describe, &p.choice, &p.default, &p.env),
                    )
                })
                .collect();
            sections.push(format!("ARGS:\n{}", render_items(&items, term_width)));
        }
        if self.has_user_flag_options() {
            let all_double = self.flag_options.iter().all(|f| f.long_name.starts_with("--"));
            let items: Vec<(String, String, Vec<String>)> = self
                .flag_options
                .iter()
                .map(|f| {
                    (
                        f.render_body(all_double),
                        f.describe.clone(),
                        render_extra_info(&f.describe, &f.choice, &f.default, &f.env),
                    )
                })
                .collect();
            sections.push(format!("OPTIONS:\n{}", render_items(&items, term_width)));
        }
        if !self.subcommands.is_empty() {
            let items: Vec<(String, String, Vec<String>)> = self
                .subcommands
                .iter()
                .map(|c| {
                    let mut extra = Vec::new();
                    if !c.aliases.is_empty() {
                        extra.push(format!("[aliases: {}]", c.aliases.join(", ")));
                    }
                    if c.default_subcommand {
                        extra.push("[default]".to_string());
                    }
                    (c.name_str(), c.describe_head().to_string(), extra)
                })
                .collect();
            sections.push(format!("COMMANDS:\n{}", render_items(&items, term_width)));
        }
        if !self.envs.is_empty() {
            let items: Vec<(String, String, Vec<String>)> = self
                .envs
                .iter()
                .map(|e| {
                    (
                        e.render_name(),
                        e.describe.clone(),
                        render_extra_info(&e.describe, &e.choice, &e.default, &None),
                    )
                })
                .collect();
            sections.push(format!("ENVIRONMENTS:\n{}", render_items(&items, term_width)));
        }
        format!("{}\n", sections.join("\n\n"))
    }

    // ---------------- json -----------------
    pub fn to_json(&self) -> Json {
        let mut items: Vec<(String, Json)> = vec![
            ("name".into(), Json::str(self.name_str())),
            ("describe".into(), Json::str(&self.describe)),
            ("version".into(), Json::opt_str(&self.version)),
            ("aliases".into(), Json::strs(&self.aliases)),
            (
                "flag_options".into(),
                Json::Arr(self.flag_options.iter().map(|f| f.to_json()).collect()),
            ),
            (
                "positionals".into(),
                Json::Arr(self.positionals.iter().map(|f| f.to_json()).collect()),
            ),
            (
                "envs".into(),
                Json::Arr(self.envs.iter().map(|f| f.to_json()).collect()),
            ),
            (
                "subcommands".into(),
                Json::Arr(self.subcommands.iter().map(|f| f.to_json()).collect()),
            ),
        ];
        if !self.require_tools.is_empty() {
            items.push(("require_tools".into(), Json::strs(&self.require_tools)));
        }
        if self.combine_shorts {
            items.push(("combine_shorts".into(), Json::Bool(true)));
        }
        if let Some(d) = &self.dotenv {
            items.push(("dotenv".into(), Json::str(d)));
        }
        if !self.metadata.is_empty() {
            items.push((
                "metadata".into(),
                Json::Obj(
                    self.metadata
                        .iter()
                        .map(|(k, v)| (k.clone(), Json::opt_str(v)))
                        .collect(),
                ),
            ));
        }
        items.push(("command_fn".into(), Json::opt_str(&self.fn_name)));
        Json::Obj(items)
    }
}

/// Render a help section with two columns, or multi-line format
pub fn render_items(items: &[(String, String, Vec<String>)], term_width: Option<usize>) -> String {
    let multiline = items.iter().any(|(_, d, _)| d.contains('\n'));
    let mut out = Vec::new();
    if multiline {
        for (name, describe, extra) in items {
            let mut block = format!("  {name}\n");
            let indent = "          ";
            let width = term_width.map(|w| w.saturating_sub(10));
            let mut body_lines: Vec<String> = Vec::new();
            if describe.contains('\n') {
                for l in wrap_text_opt(describe, width) {
                    body_lines.push(l);
                }
                for e in extra {
                    body_lines.push(e.clone());
                }
            } else {
                let mut text = describe.clone();
                for e in extra {
                    if !text.is_empty() {
                        text.push(' ');
                    }
                    text.push_str(e);
                }
                if !text.is_empty() {
                    for l in wrap_text_opt(&text, width) {
                        body_lines.push(l);
                    }
                }
            }
            for l in body_lines {
                if l.is_empty() {
                    block.push('\n');
                } else {
                    block.push_str(&format!("{indent}{l}\n"));
                }
            }
            out.push(block);
        }
        let mut s = out.join("\n");
        if s.ends_with('\n') {
            s.pop();
        }
        s
    } else {
        let name_width = items.iter().map(|(n, _, _)| n.chars().count()).max().unwrap_or(0);
        for (name, describe, extra) in items {
            let mut text = describe.clone();
            for e in extra {
                if !text.is_empty() {
                    text.push(' ');
                }
                text.push_str(e);
            }
            if text.is_empty() {
                out.push(format!("  {name}"));
            } else {
                let pad = name_width - name.chars().count();
                let indent = 2 + name_width + 2;
                let width = term_width.map(|w| w.saturating_sub(indent));
                let lines = wrap_text_opt(&text, width);
                let mut s = format!("  {name}{}  {}", " ".repeat(pad), lines[0]);
                for l in &lines[1..] {
                    s.push('\n');
                    s.push_str(&" ".repeat(indent));
                    s.push_str(l);
                }
                out.push(s);
            }
        }
        out.join("\n")
    }
}
