        return false;
    }
    let key = arg.split_once('=').map(|(k, _)| k).unwrap_or(arg);
    if key.chars().any(|c| c.is_whitespace()) {
        return false;
    }
    let mut chars = arg.chars();
    let first = match chars.next() {
        Some(c) => c,
        None => return false,
    };
    let second = chars.next();
    if first == '-' && signs.contains('-') {
        if arg.len() == 1 {
            return false;
        }
        if arg.starts_with("---") {
            return false;
        }
        return true;
    }
    if first == '+' && signs.contains('+') {
        if arg.len() == 1 {
            return false;
        }
        if second == Some('+') {
            return false;
        }
        return true;
    }
    false
}

impl<'a> Matcher<'a> {
    pub fn new(root: &'a Command, args: &[String], compgen: bool) -> Self {
        let mut matcher = Matcher {
            root,
            args: args.to_vec(),
            cmds: vec![root],
            cmd_arg_indexes: vec![0],
            flag_option_args: vec![vec![]],
            positional_args: vec![],
            dash: None,
            symbol_args: vec![],
            arg_comp: ArgComp::Any,
            split_last_arg_at: None,
            help: false,
            version: false,
            error: None,
            compgen,
            script_path: None,
            term_width: None,
            envs: HashMap::new(),
        };
        matcher.run();
        matcher
    }

    pub fn set_script_path(&mut self, path: &str) {
        self.script_path = Some(path.to_string());
    }

    pub fn set_term_width(&mut self, width: Option<usize>) {
        self.term_width = width;
    }

    pub fn set_envs(&mut self, envs: HashMap<String, String>) {
        self.envs = envs;
    }

    fn cmd(&self) -> &'a Command {
        self.cmds[self.cmds.len() - 1]
    }

    fn run(&mut self) {
        let args = self.args.clone();
        let len = args.len();
        let mut i = 1;
        let mut rest_positional = false;
        while i < len {
            let arg = &args[i];
            let is_last = i == len - 1;
            let cmd = self.cmd();
            if rest_positional {
                self.positional_args.push(arg.clone());
                if is_last {
                    self.arg_comp = ArgComp::CommandOrPositional;
                }
                i += 1;
                continue;
            }
            if arg == "--" && !(self.compgen && is_last) {
                self.dash = Some(self.positional_args.len());
                rest_positional = true;
                i += 1;
                continue;
            }
            let signs = cmd.flag_option_signs();
            let flag_like = if self.compgen && is_last {
                arg.starts_with('-') && arg.len() > 1 || is_flag_or_option_like(arg, &signs)
            } else {
                is_flag_or_option_like(arg, &signs)
            };
            if flag_like {
                // in compgen mode, the last arg
                if self.compgen && is_last {
                    if let Some(eq) = arg.find('=') {
                        let key = &arg[..eq];
                        if let Some(param) = cmd.find_flag_option(key) {
                            if param.flag {
                                // the original panics here; emulate
                                eprintln!("\nthread 'main' panicked at src/matcher.rs:1422:53:\ncalled `Option::unwrap()` on a `None` value\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace");
                                std::process::exit(101);
                            }
                            let value = arg[eq + 1..].to_string();
                            self.flag_option_args[self.cmds.len() - 1].push(FlagOptionArg {
                                raw: key.to_string(),
                                values: vec![value],
                                param,
                                index: i,
                            });
                            self.split_last_arg_at = Some(eq + 1);
                            self.arg_comp = ArgComp::OptionValue(param, 0);
                            i += 1;
                            continue;
                        }
                        // prefixed option with '='? e.g. -Xa=b
                        if let Some(param) = self.find_prefixed_option(cmd, key) {
                            let value = arg[param.long_name.len()..].to_string();
                            self.flag_option_args[self.cmds.len() - 1].push(FlagOptionArg {
                                raw: param.long_name.clone(),
                                values: vec![value],
                                param,
                                index: i,
                            });
                            self.split_last_arg_at = Some(param.long_name.len());
                            self.arg_comp = ArgComp::OptionValue(param, 0);
                            i += 1;
                            continue;
                        }
                        self.arg_comp = ArgComp::FlagOrOption;
                        i += 1;
                        continue;
                    }
                    if let Some(param) = cmd.find_flag_option(arg) {
                        if param.is_help() {
                            self.help = true;
                        } else if param.is_version() {
                            self.version = true;
                        }
                        self.flag_option_args[self.cmds.len() - 1].push(FlagOptionArg {
                            raw: arg.clone(),
                            values: vec![],
                            param,
                            index: i,
                        });
                        self.arg_comp = ArgComp::FlagOrOption;
                        i += 1;
                        continue;
                    }
                    if let Some(param) = self.find_prefixed_option(cmd, arg) {
                        let value = arg[param.long_name.len()..].to_string();
                        self.flag_option_args[self.cmds.len() - 1].push(FlagOptionArg {
                            raw: param.long_name.clone(),
                            values: vec![value],
                            param,
                            index: i,
                        });
                        self.split_last_arg_at = Some(param.long_name.len());
                        self.arg_comp = ArgComp::OptionValue(param, 0);
                        i += 1;
                        continue;
                    }
                    if self.root.combine_shorts {
                        if let Some(list) = self.match_combine_shorts(cmd, arg) {
                            let mut all_flags = true;
                            for (idx, p) in list.iter().enumerate() {
                                self.flag_option_args[self.cmds.len() - 1].push(FlagOptionArg {
                                    raw: format!("-{}", arg.chars().nth(idx + 1).unwrap()),
                                    values: vec![],
                                    param: p,
                                    index: i,
                                });
                                if !p.flag {
                                    all_flags = false;
                                }
                            }
                            let _ = all_flags;
                            self.arg_comp = ArgComp::FlagOrOptionCombine(arg.clone());
                            i += 1;
                            continue;
                        }
                    }
                    self.arg_comp = ArgComp::FlagOrOption;
                    i += 1;
                    continue;
                }
                // normal processing
                let (key, eq_value) = match arg.split_once('=') {
                    Some((k, v)) => (k.to_string(), Some(v.to_string())),
                    None => (arg.clone(), None),
                };
                let mut matched_param: Option<(&'a FlagOptionParam, String, Option<String>)> = None;
                if let Some(param) = cmd.find_flag_option(&key) {
                    matched_param = Some((param, key.clone(), eq_value.clone()));
                } else if let Some(param) = self.find_prefixed_option(cmd, &key) {
                    let value = key[param.long_name.len()..].to_string();
                    let value = match &eq_value {
                        Some(v) => format!("{value}={v}"),
                        None => value,
                    };
                    matched_param = Some((param, param.long_name.clone(), Some(value)));
                } else if self.root.combine_shorts && eq_value.is_none() {
                    if let Some(list) = self.match_combine_shorts(cmd, arg) {
                        // expand: all but last take no values; last may take values
                        let n = list.len();
                        for (idx, p) in list.iter().enumerate() {
                            let raw = format!("-{}", arg.chars().nth(idx + 1).unwrap());
                            if idx + 1 < n {
                                if p.is_help() {
                                    self.help = true;
                                } else if p.is_version() {
                                    self.version = true;
                                }
                                self.flag_option_args[self.cmds.len() - 1].push(FlagOptionArg {
                                    raw,
                                    values: vec![],
                                    param: p,
                                    index: i,
                                });
                            } else {
                                matched_param = Some((p, raw, None));
                            }
                        }
                    }
                }
                match matched_param {
                    Some((param, raw, eq_value)) => {
                        if param.is_help() {
                            self.help = true;
                            self.flag_option_args[self.cmds.len() - 1].push(FlagOptionArg {
                                raw,
                                values: vec![],
                                param,
                                index: i,
                            });
                            i += 1;
                            continue;
                        }
                        if param.is_version() {
                            self.version = true;
                            self.flag_option_args[self.cmds.len() - 1].push(FlagOptionArg {
                                raw,
                                values: vec![],
                                param,
                                index: i,
                            });
                            i += 1;
                            continue;
                        }
                        if param.flag {
                            if eq_value.is_some() && !self.compgen {
                                self.error = Some(MatchError::NoFlagValue(param.long_name.clone()));
                                break;
                            }
                            self.flag_option_args[self.cmds.len() - 1].push(FlagOptionArg {
                                raw,
                                values: vec![],
                                param,
                                index: i,
                            });
                            i += 1;
                            continue;
                        }
                        // option: take values
                        let mut values: Vec<String> = Vec::new();
                        let mut consumed = 0;
                        if let Some(v) = eq_value {
                            values.push(v);
                        } else if param.assigned {
                            // assigned options require '='; take no values
                        } else {
                            let max = param.num_args.1;
                            let mut j = i + 1;
                            while j < len && values.len() < max {
                                let next = &args[j];
                                if param.terminated {
                                    values.push(next.clone());
                                    j += 1;
                                    continue;
                                }
                                if next == "--" {
                                    break;
                                }
                                if is_flag_or_option_like(next, &signs) && next.len() > 1 {
                                    break;
                                }
                                values.push(next.clone());
                                j += 1;
                            }
                            consumed = j - (i + 1);
                            if self.compgen && j == len && consumed > 0 && (param.terminated || values.len() <= max) {
                                // last arg is a value of this option
                                let idx = values.len() - 1;
                                self.arg_comp = if param.terminated {
                                    ArgComp::Any
                                } else {
                                    ArgComp::OptionValue(param, idx)
                                };
                            }
                        }
                        self.flag_option_args[self.cmds.len() - 1].push(FlagOptionArg {
                            raw,
                            values,
                            param,
                            index: i,
                        });
                        i += 1 + consumed;
                        continue;
                    }
                    None => {
                        if self.compgen {
                            i += 1;
                            continue;
                        }
                        if self.help || self.version {
                            i += 1;
                            continue;
                        }
                        self.error = Some(MatchError::UnknownArgument(key));
                        break;
                    }
                }
            }
            // symbols
            if !cmd.symbols.is_empty() {
                if let Some(c) = arg.chars().next() {
                    if let Some(sym) = cmd.symbols.iter().find(|s| s.ch == c) {
                        self.symbol_args.push((sym, arg[c.len_utf8()..].to_string()));
                        if self.compgen && is_last {
                            self.arg_comp = ArgComp::Symbol(c);
                        }
                        i += 1;
                        continue;
                    }
                }
            }
            // subcommand
            if self.positional_args.is_empty() && !cmd.subcommands.is_empty() {
                if let Some(sub) = cmd.find_subcommand(arg) {
                    if !(self.compgen && is_last) {
                        self.cmds.push(sub);
                        self.cmd_arg_indexes.push(i);
                        self.flag_option_args.push(vec![]);
                        i += 1;
                        continue;
                    }
                }
            }
            // positional
            self.positional_args.push(arg.clone());
            if self.compgen && is_last {
                self.arg_comp = ArgComp::CommandOrPositional;
            }
            // terminated positional handling
            if let Some(idx) = self.terminated_positional_reached(cmd) {
                let _ = idx;
                rest_positional = true;
            }
            i += 1;
        }
    }

    fn terminated_positional_reached(&self, cmd: &Command) -> Option<usize> {
        // if the number of positionals reaches the terminated positional, the rest are positional
        let n = self.positional_args.len();
        for (idx, p) in cmd.positionals.iter().enumerate() {
            if p.terminated && n > idx {
                return Some(idx);
            }
        }
        None
    }

    fn find_prefixed_option(&self, cmd: &'a Command, key: &str) -> Option<&'a FlagOptionParam> {
        cmd.flag_options
            .iter()
            .find(|p| p.prefixed && key.len() > p.long_name.len() && key.starts_with(&p.long_name))
    }

    fn match_combine_shorts(&self, cmd: &'a Command, arg: &str) -> Option<Vec<&'a FlagOptionParam>> {
        if !arg.starts_with('-') || arg.starts_with("--") || arg.chars().count() < 3 {
            return None;
        }
        let mut list = Vec::new();
        for c in arg[1..].chars() {
            let name = format!("-{c}");
            let param = cmd.flag_options.iter().find(|p| p.short_name.as_deref() == Some(&name))?;
            if param.is_help() || param.is_version() {
                return None;
            }
            list.push(param);
        }
        Some(list)
    }

    // ------------------------------------------------------------------

    pub fn to_arg_values(&self) -> ArgValuesResult {
        let cmd = self.cmd();
        if self.help {
            return ArgValuesResult::Err(MatchError::DisplayHelp, cmd);
        }
        if self.version {
            return ArgValuesResult::Err(MatchError::DisplayVersion, cmd);
        }
        if let Some(err) = &self.error {
            return ArgValuesResult::Err(err.clone(), cmd);
        }
        // validate flag options at every level
        for (level, level_cmd) in self.cmds.iter().enumerate() {
            let args = &self.flag_option_args[level];
            // multiple times
            for param in level_cmd.flag_options.iter() {
                if param.multiple_occurs {
                    continue;
                }
                let count = args.iter().filter(|a| a.param.id == param.id).count();
                if count > 1 {
                    return ArgValuesResult::Err(
                        MatchError::NotMultipleArgument(param.long_name.clone()),
                        cmd,
                    );
                }
            }
            // values
            for arg in args.iter() {
                let param = arg.param;
                if param.flag {
                    continue;
                }
                let values = self.split_values(param, &arg.values);
                let (min, max) = param.num_args;
                if arg.values.len() < min || arg.values.len() > max {
                    return ArgValuesResult::Err(
                        MatchError::MismatchValues(param.render_long_with_notations()),
                        cmd,
                    );
                }
                if let Some(choice) = &param.choice {
                    if let Some(err) = self.validate_choice(
                        choice,
                        &values,
                        &format!("<{}>", param.render_first_notation()),
                    ) {
                        return ArgValuesResult::Err(err, cmd);
                    }
                }
            }
            // missing required
            let mut missing = Vec::new();
            for param in level_cmd.flag_options.iter() {
                if param.required && !args.iter().any(|a| a.param.id == param.id) {
                    missing.push(param.render_long_with_notations());
                }
            }
            if !missing.is_empty() {
                return ArgValuesResult::Err(MatchError::MissingRequiredArguments(missing), cmd);
            }
        }
        // subcommand handling
        let mut cmd = cmd;
        let mut positional_args = self.positional_args.clone();
        let mut dash = self.dash;
        if !cmd.subcommands.is_empty() && !(cmd.is_root && cmd.exist_main_fn) {
            if let Some(sub) = cmd.find_default_subcommand() {
                cmd = sub;
            } else if positional_args.first().map(|v| v == "help").unwrap_or(false) {
                return self.handle_help_positional(cmd, &positional_args);
            } else if positional_args.is_empty() {
                let any_flag = self.flag_option_args.iter().any(|v| !v.is_empty());
                if !any_flag && self.symbol_args.is_empty() {
                    return ArgValuesResult::Err(MatchError::DisplayHelp, cmd);
                }
                return ArgValuesResult::Err(
                    MatchError::RequireSubcommand(None, cmd.list_subcommand_names()),
                    cmd,
                );
            } else {
                return ArgValuesResult::Err(
                    MatchError::RequireSubcommand(
                        Some(positional_args[0].clone()),
                        cmd.list_subcommand_names(),
                    ),
                    cmd,
                );
            }
        } else if positional_args.first().map(|v| v == "help").unwrap_or(false) {
            return self.handle_help_positional(cmd, &positional_args);
        }
        // positionals
        let mut positional_values: Vec<Option<Vec<String>>> = vec![None; cmd.positionals.len()];
        if !positional_args.is_empty() {
            // split by delimiter first? The build splits after match. We follow build: match then split.
            let flags: Vec<bool> = cmd.positionals.iter().map(|p| p.multiple).collect();
            let (ranges, extra) = match_positionals(&flags, positional_args.len(), dash);
            if let Some(idx) = extra {
                return ArgValuesResult::Err(
                    MatchError::UnknownArgument(positional_args[idx].clone()),
                    cmd,
                );
            }
            // split with delimiters and rebuild positional_args
            let mut new_positional_args: Vec<String> = Vec::new();
            for (pi, range) in ranges.iter().enumerate() {
                let param = &cmd.positionals[pi];
                let (start, size) = *range;
                let vals: Vec<String> = positional_args[start..start + size].to_vec();
                let vals = if let Some(d) = param.delimiter {
                    vals.iter()
                        .flat_map(|v| v.split(d).map(|x| x.to_string()).collect::<Vec<_>>())
                        .collect()
                } else {
                    vals
                };
                new_positional_args.extend(vals.iter().cloned());
                positional_values[pi] = Some(vals);
            }
            if ranges.len() < cmd.positionals.len() {
                // no extra args beyond ranges handled
            }
            // keep positionals beyond matched (none since extra would error)
            positional_args = new_positional_args;
            dash = None;
            let _ = dash;
            // validate choices
            for (pi, param) in cmd.positionals.iter().enumerate() {
                if let (Some(vals), Some(choice)) = (&positional_values[pi], &param.choice) {
                    if let Some(err) = self.validate_choice(choice, vals, &param.render_notation()) {
                        return ArgValuesResult::Err(err, cmd);
                    }
                }
            }
        }
        // missing required positionals
        let mut missing = Vec::new();
        for (pi, param) in cmd.positionals.iter().enumerate() {
            if positional_values[pi].is_none() {
                // env / default
                if let Some(env) = &param.env {
                    if let Some(v) = self.envs.get(env) {
                        positional_values[pi] = Some(vec![v.clone()]);
                        positional_args.push(v.clone());
                        continue;
                    }
                }
                if let Some(d) = &param.default {
                    let v = match d {
                        DefaultValue::Value(v) => v.clone(),
                        DefaultValue::Fn(f) => format!("`{f}`"),
                    };
                    positional_values[pi] = Some(vec![v.clone()]);
                    positional_args.push(v);
                    continue;
                }
                if param.required {
                    missing.push(param.render_notation());
                }
            }
        }
        if !missing.is_empty() {
            return ArgValuesResult::Err(MatchError::MissingRequiredArguments(missing), cmd);
        }
        // envs
        let mut missing_envs = Vec::new();
        for env in cmd.envs.iter() {
            match self.envs.get(&env.id) {
                Some(v) => {
                    if let Some(choice) = &env.choice {
                        if let Some(err) = self.validate_env_choice(choice, v, &env.id) {
                            return ArgValuesResult::Err(err, cmd);
                        }
                    }
                }
                None => {
                    if env.required {
                        missing_envs.push(env.id.clone());
                    }
                }
            }
        }
        if !missing_envs.is_empty() {
            return ArgValuesResult::Err(MatchError::MissingRequiredEnvironments(missing_envs), cmd);
        }
        ArgValuesResult::Ok(ArgValues {
            cmd,
            positional_args,
            positional_values,
        })
    }

    fn handle_help_positional(&self, cmd: &'a Command, positional_args: &[String]) -> ArgValuesResult<'a> {
        if positional_args.len() == 1 {
            return ArgValuesResult::Err(MatchError::DisplayHelp, cmd);
        }
        let name = &positional_args[1];
        match cmd.find_subcommand(name) {
            Some(sub) => ArgValuesResult::Err(MatchError::DisplayHelp, sub),
            None => ArgValuesResult::Err(
                MatchError::InvalidSubcommandValue(name.clone(), cmd.list_subcommand_names()),
                cmd,
            ),
        }
    }

    fn split_values(&self, param: &FlagOptionParam, values: &[String]) -> Vec<String> {
        if let Some(d) = param.delimiter {
            values
                .iter()
                .flat_map(|v| v.split(d).map(|x| x.to_string()).collect::<Vec<_>>())
                .collect()
        } else {
            values.to_vec()
        }
    }

    fn get_choices(&self, choice: &ChoiceValue) -> Option<Vec<String>> {
        match choice {
            ChoiceValue::Values(values) => Some(values.clone()),
            ChoiceValue::Fn(f, validate) => {
                if !validate {
                    return None;
                }
                let script_path = self.script_path.as_ref()?;
                let outputs = run_param_fns(script_path, &[f.as_str()], &self.args, HashMap::new())?;
                Some(
                    outputs[0]
                        .lines()
                        .map(|v| v.trim().to_string())
                        .filter(|v| !v.is_empty())
                        .collect(),
                )
            }
        }
    }

    fn validate_choice(&self, choice: &ChoiceValue, values: &[String], name: &str) -> Option<MatchError> {
        let choices = self.get_choices(choice)?;
        for v in values {
            if !choices.contains(v) {
                return Some(MatchError::InvalidValue(v.clone(), name.to_string(), choices));
            }
        }
        None
    }

    fn validate_env_choice(&self, choice: &ChoiceValue, value: &str, name: &str) -> Option<MatchError> {
        let choices = self.get_choices(choice)?;
        if !choices.contains(&value.to_string()) {
            return Some(MatchError::InvalidEnvironment(value.to_string(), name.to_string(), choices));
        }
        None
    }

    /// Build the variable assignment lines (without hooks)
    pub fn build_variables(&self, values: &ArgValues<'a>, internal: bool) -> Vec<String> {
        let mut vars: Vec<String> = Vec::new();
        for (level, level_cmd) in self.cmds.iter().enumerate() {
            let args = &self.flag_option_args[level];
            for param in level_cmd.flag_options.iter() {
                if param.is_help() || param.is_version() {
                    continue;
                }
                let matched: Vec<&FlagOptionArg> = args.iter().filter(|a| a.param.id == param.id).collect();
                let var = param.var_name();
                if matched.is_empty() {
                    if level == self.cmds.len() - 1 || true {
                        if let Some(env) = &param.env {
                            if let Some(v) = self.envs.get(env) {
                                if param.flag {
                                    if crate::utils::is_true_value(v) {
                                        vars.push(format!("{var}=1"));
                                    }
                                } else if param.multiple_values {
                                    vars.push(format!("{var}=( {} )", escape_shell_word(v)));
                                } else {
                                    vars.push(format!("{var}={}", escape_shell_word(v)));
                                }
                                continue;
                            }
                        }
                        if let Some(d) = &param.default {
                            let v = match d {
                                DefaultValue::Value(v) => escape_shell_word(v),
                                DefaultValue::Fn(f) => format!("`{f}`"),
                            };
                            if param.multiple_values {
                                vars.push(format!("{var}=( {v} )"));
                            } else {
                                vars.push(format!("{var}={v}"));
                            }
                        }
                    }
                    continue;
                }
                if param.flag {
                    vars.push(format!("{var}={}", matched.len()));
                } else {
                    let mut all_values: Vec<String> = Vec::new();
                    for m in matched.iter() {
                        all_values.extend(self.split_values(param, &m.values));
                    }
                    if param.multiple_values {
                        vars.push(format!("{var}=( {} )", escape_shell_words(&all_values)));
                    } else {
                        let v = all_values.first().cloned().unwrap_or_default();
                        vars.push(format!("{var}={}", escape_shell_word(&v)));
                    }
                }
            }
        }
        for (sym, value) in self.symbol_args.iter() {
            vars.push(format!("{}={}", sym.var_name(), escape_shell_word(value)));
        }
        let cmd = values.cmd;
        for (pi, param) in cmd.positionals.iter().enumerate() {
            if let Some(vals) = &values.positional_values[pi] {
                let var = param.var_name();
                if param.multiple {
                    vars.push(format!("{var}=( {} )", escape_shell_words(vals)));
                } else {
                    let v = vals.first().cloned().unwrap_or_default();
                    if v.starts_with('`') && v.ends_with('`') && param.default.is_some() && matches!(param.default, Some(DefaultValue::Fn(_))) {
                        vars.push(format!("{var}={v}"));
                    } else {
                        vars.push(format!("{var}={}", escape_shell_word(&v)));
                    }
                }
            }
        }
        vars.push(format!("argc__args=( {} )", escape_shell_words(&self.args)));
        if internal {
            vars.push(format!(
                "argc__cmd_arg_index={}",
                self.cmd_arg_indexes[self.cmd_arg_indexes.len() - 1]
            ));
            if self.cmds.len() > 1 {
                if let Some(f) = &self.cmd().fn_name {
                    vars.push(format!("argc__cmd_fn={f}"));
                }
            }
            if let Some(opt) = self.last_option_var() {
                vars.push(format!("argc__option={opt}"));
            }
        } else {
            let fn_name = if cmd.is_root {
                if cmd.exist_main_fn {
                    Some("main".to_string())
                } else {
                    None
                }
            } else {
                cmd.fn_name.clone()
            };
            if let Some(f) = fn_name {
                vars.push(format!("argc__fn={f}"));
            }
        }
        let mut positionals = values.positional_args.clone();
        if positionals.iter().any(|v| v.starts_with('`') && v.ends_with('`')) {
            // default fn values keep backticks unescaped
        }
        let rendered: Vec<String> = positionals
            .iter_mut()
            .map(|v| {
                if v.starts_with('`') && v.ends_with('`') && v.len() > 2 {
                    v.clone()
                } else {
                    escape_shell_word(v)
                }
            })
            .collect();
        vars.push(format!("argc__positionals=( {} )", rendered.join(" ")));
        vars
    }

    fn last_option_var(&self) -> Option<String> {
        let last_index = self.args.len() - 1;
        for level_args in self.flag_option_args.iter() {
            for a in level_args.iter() {
                if a.index == last_index || (a.index < last_index && a.index + a.values.len() >= last_index && !a.param.flag && !a.values.is_empty() && self.value_consumed_last(a)) {
                    return Some(a.param.var_name());
                }
            }
        }
        match &self.arg_comp {
            ArgComp::OptionValue(p, _) => Some(p.var_name()),
            _ => None,
        }
    }

    fn value_consumed_last(&self, a: &FlagOptionArg) -> bool {
        // values are consecutive args after index
        let last_index = self.args.len() - 1;
        if self.args[a.index].contains('=') && a.index == last_index {
            return true;
        }
        a.index + a.values.len() == last_index
    }

    /// lenient values for compgen / internal
    pub fn to_arg_values_lenient(&self) -> ArgValues<'a> {
        let cmd = self.cmd();
        let flags: Vec<bool> = cmd.positionals.iter().map(|p| p.multiple).collect();
        let mut positional_values: Vec<Option<Vec<String>>> = vec![None; cmd.positionals.len()];
        let (ranges, _extra) = match_positionals(&flags, self.positional_args.len(), self.dash);
        let mut positional_args: Vec<String> = Vec::new();
        for (pi, range) in ranges.iter().enumerate() {
            let param = &cmd.positionals[pi];
            let (start, size) = *range;
            let vals: Vec<String> = self.positional_args[start..start + size].to_vec();
            let vals = if let Some(d) = param.delimiter {
                vals.iter()
                    .flat_map(|v| v.split(d).map(|x| x.to_string()).collect::<Vec<_>>())
                    .collect()
            } else {
                vals
            };
            positional_args.extend(vals.iter().cloned());
            positional_values[pi] = Some(vals);
        }
        // remaining positionals beyond params
        let consumed: usize = ranges.iter().map(|(_, s)| s).sum();
        if consumed < self.positional_args.len() {
            positional_args.extend(self.positional_args[consumed..].iter().cloned());
        }
        ArgValues {
            cmd,
            positional_args,
            positional_values,
        }
    }

    pub fn compgen_state(&self) -> (&'a Command, &ArgComp<'a>, Option<usize>, &[String], Option<usize>) {
        (
            self.cmd(),
            &self.arg_comp,
            self.split_last_arg_at,
            &self.positional_args,
            self.dash,
        )
    }

    pub fn flag_option_used(&self, param: &FlagOptionParam) -> bool {
        let level = self.cmds.len() - 1;
        self.flag_option_args[level].iter().any(|a| a.param.id == param.id)
    }

    pub fn used_short_chars(&self) -> Vec<char> {
        let level = self.cmds.len() - 1;
        let mut out = Vec::new();
        for a in self.flag_option_args[level].iter() {
            if let Some(s) = &a.param.short_name {
                if let Some(c) = s.chars().nth(1) {
                    out.push(c);
                }
            }
        }
        out
    }

    pub fn args(&self) -> &[String] {
        &self.args
    }

    pub fn cmds(&self) -> &[&'a Command] {
        &self.cmds
    }
}

pub struct ArgValues<'a> {
    pub cmd: &'a Command,
    pub positional_args: Vec<String>,
    pub positional_values: Vec<Option<Vec<String>>>,
}

pub enum ArgValuesResult<'a> {
    Ok(ArgValues<'a>),
    Err(MatchError, &'a Command),
}

/// Distribute positional args among params. Returns ranges (start, size) for each param
/// matched, and the index of the first unexpected arg if any.
pub fn match_positionals(multiples: &[bool], args_len: usize, dash: Option<usize>) -> (Vec<(usize, usize)>, Option<usize>) {
    let mut ranges = Vec::new();
    if args_len == 0 {
        return (ranges, None);
    }
    let params_len = multiples.len();
    let mut arg_index = 0;
    let mut param_index = 0;
    while param_index < params_len && arg_index < args_len {
        let takes;
        if multiples[param_index] {
            if param_index == 0
                && dash.map(|d| d > 0).unwrap_or(false)
                && params_len == 2
                && multiples[1]
            {
                takes = dash.unwrap();
            } else {
                let arg_diff = args_len - arg_index;
                let param_diff = params_len - param_index;
                if arg_diff > param_diff {
                    takes = arg_diff - param_diff + 1;
                } else {
                    takes = 1;
                }
            }
        } else {
            takes = 1;
        }
        ranges.push((arg_index, takes));
        arg_index += takes;
        param_index += 1;
    }
    if arg_index < args_len {
        return (ranges, Some(arg_index));
    }
    (ranges, None)
}

pub fn render_error(err: &MatchError, cmd: &Command) -> String {
    match err {
        MatchError::DisplayHelp | MatchError::DisplayVersion | MatchError::DisplaySubcommandHelp(_) => String::new(),
        MatchError::InvalidSubcommand => String::new(),
        MatchError::UnknownArgument(v) => format!("error: unexpected argument `{v}` found"),
        MatchError::MissingRequiredArguments(list) => format!(
            "error: the following required arguments were not provided:\n{}",
            list.iter().map(|v| format!("  {v}")).collect::<Vec<_>>().join("\n")
        ),
        MatchError::MissingRequiredEnvironments(list) => format!(
            "error: the following required environments were not provided:\n{}",
            list.iter().map(|v| format!("  {v}")).collect::<Vec<_>>().join("\n")
        ),
        MatchError::NotMultipleArgument(name) => {
            format!("error: the argument `{name}` cannot be used multiple times")
        }
        MatchError::InvalidValue(value, name, choices) => format!(
            "error: invalid value `{value}` for `{name}`\n  [possible values: {}]",
            choices.join(", ")
        ),
        MatchError::InvalidEnvironment(value, name, choices) => format!(
            "error: invalid value `{value}` for environment variable `{name}`\n  [possible values: {}]",
            choices.join(", ")
        ),
        MatchError::MismatchValues(name) => format!("error: incorrect number of values for `{name}`"),
        MatchError::NoFlagValue(name) => format!("error: flag `{name}` don't accept any value"),
        MatchError::NoMoreValue(name, value) => {
            format!("error: unexpected value `{value}` for `{name}` found")
        }
        MatchError::InvalidSubcommandValue(value, names) => format!(
            "error: invalid value `{value}` for `<command>`\n  [possible values: {}]",
            names.join(", ")
        ),
        MatchError::RequireSubcommand(value, names) => {
            let name = cmd.name_str();
            match value {
                Some(v) => format!(
                    "error: `{name}` requires a subcommand but '{v}' is not one of them\n  [subcommands: {}]",
                    names.join(", ")
                ),
                None => format!(
                    "error: `{name}` requires a subcommand but one was not provided\n  [subcommands: {}]",
                    names.join(", ")
                ),
            }
        }
    }
}

pub fn encode_vars(vars: &[String]) -> String {
    let joined: String = vars.iter().map(|v| format!("{v};")).collect();
    base64_encode(joined.as_bytes())
}

pub fn positional_param_var(p: &PositionalParam) -> String {
    p.var_name()
}

