                    let mut p = PathBuf::from(outpath);
                    if p.is_dir() || outpath.ends_with('/') {
                        if let Err(e) = std::fs::create_dir_all(&p) {
                            return fail(&format!("Failed to create dir at '{outpath}'\n\nCaused by:\n    {e}"));
                        }
                        p = p.join(Path::new(&script_path).file_name().unwrap_or_default());
                    }
                    if let Some(parent) = p.parent() {
                        if !parent.as_os_str().is_empty() && !parent.exists() {
                            let _ = std::fs::create_dir_all(parent);
                        }
                    }
                    if let Err(e) = std::fs::write(&p, &output) {
                        return fail(&format!("Failed to write script to '{}'\n\nCaused by:\n    {e}", p.display()));
                    }
                    #[cfg(unix)]
                    {
                        use std::os::unix::fs::PermissionsExt;
                        let _ = std::fs::set_permissions(&p, std::fs::Permissions::from_mode(0o755));
                    }
