fn get_shell_or_fail() -> Result<PathBuf, i32> {
    match utils::get_shell_path() {
        Some(p) => Ok(p),
        None => Err(fail("Shell not found")),
    }
}

fn run_script(script_path: &str, script_args: &[String]) -> i32 {
    let shell = match get_shell_or_fail() {
        Ok(p) => p,
        Err(code) => return code,
    };
    let script = Path::new(script_path);
    let script_dir = script.parent().map(|p| p.to_path_buf());
    let cwd = std::env::current_dir().ok();
    let mut cmd = ProcCommand::new(&shell);
    cmd.arg(script_path).args(script_args);
    if let Some(cwd) = &cwd {
        cmd.env("ARGC_PWD", cwd.to_string_lossy().to_string());
    }
    if let Some(dir) = &script_dir {
        if !dir.as_os_str().is_empty() {
            cmd.current_dir(dir);
        }
    }
    match cmd.status() {
        Ok(status) => status.code().unwrap_or(1),
        Err(e) => fail(&format!("Failed to run `{}`\n\nCaused by:\n    {e}", shell.display())),
    }
}

fn find_argcfile() -> Option<PathBuf> {
    let names = ["Argcfile.sh", "Argcfile", "argcfile.sh", "argcfile", "ARGCFILE.sh", "ARGCFILE"];
    let mut dir = std::env::current_dir().ok()?;
    loop {
        for n in names {
            let p = dir.join(n);
            if p.is_file() {
                return Some(p);
            }
        }
        if !dir.pop() {
            return None;
        }
    }
}

fn create_argcfile(recipes: &[String]) -> i32 {
    let path = match std::env::current_dir() {
        Ok(d) => d.join("Argcfile.sh"),
        Err(_) => PathBuf::from("Argcfile.sh"),
    };
    if path.exists() {
        return fail(&format!("Already exist {}", path.display()));
    }
    let mut content = String::from("#!/usr/bin/env bash\n\nset -e\n\n");
    for r in recipes {
        content.push_str(&format!("# @cmd\n{r}() {{\n    echo TODO {r}\n}}\n\n"));
    }
    content.push_str("# See more details at https://github.com/sigoden/argc\neval \"$(argc --argc-eval \"$0\" \"$@\")\"\n");
    if let Err(e) = std::fs::write(&path, content) {
        return fail(&format!("Failed to write {}\n\nCaused by:\n    {e}", path.display()));
    }
    println!("Argcfile.sh has been successfully created.");
    0
}

fn parallel(script_path: &str, args: &[String]) -> i32 {
    let shell = match get_shell_or_fail() {
        Ok(p) => p,
        Err(code) => return code,
    };
    let mut jobs: Vec<Vec<String>> = Vec::new();
    let mut cur: Vec<String> = Vec::new();
    for a in args {
        if a == ":::" {
            if !cur.is_empty() {
                jobs.push(std::mem::take(&mut cur));
            }
        } else {
            cur.push(a.clone());
        }
    }
    if !cur.is_empty() {
        jobs.push(cur);
    }
    let mut handles = Vec::new();
    for job in jobs {
        let shell = shell.clone();
        let script_path = script_path.to_string();
        handles.push(std::thread::spawn(move || {
            let mut cmd = ProcCommand::new(&shell);
            cmd.arg("--noprofile")
                .arg("--norc")
                .arg(&script_path)
                .arg("___parallel___")
                .args(&job)
                .env("ARGC_PARALLEL", "1")
                .stdin(Stdio::null())
                .stdout(Stdio::piped())
                .stderr(Stdio::piped());
            cmd.output()
        }));
    }
    let mut failed = false;
    let mut outs: Vec<Vec<u8>> = Vec::new();
    let mut errs: Vec<Vec<u8>> = Vec::new();
    for h in handles {
        match h.join() {
            Ok(Ok(output)) => {
                if !output.status.success() {
                    failed = true;
                }
                outs.push(output.stdout);
                errs.push(output.stderr);
            }
            _ => failed = true,
        }
    }
    let stdout = std::io::stdout();
    let mut lock = stdout.lock();
    for o in outs {
        let _ = lock.write_all(&o);
    }
    let _ = lock.flush();
    let stderr = std::io::stderr();
    let mut elock = stderr.lock();
    for e in errs {
        let _ = elock.write_all(&e);
    }
    let _ = elock.flush();
    if failed {
        1
    } else {
        0
    }
}

fn load_dotenv_file(path: &str) -> HashMap<String, String> {
    let mut out = HashMap::new();
    if let Ok(content) = std::fs::read_to_string(path) {
        for line in content.lines() {
            let line = line.trim();
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            if let Some((k, v)) = line.split_once('=') {
                let k = k.trim();
                if k.is_empty() {
                    continue;
                }
                out.insert(k.to_string(), v.to_string());
            }
        }
    }
    out
}

pub fn eval(script_path: &str, script_args: &[String]) -> Result<String, String> {
    let source = std::fs::read_to_string(script_path)
        .map_err(|_| format!("Failed to load script at '{script_path}'"))?;
    if script_args.first().map(|v| v == "___internal___").unwrap_or(false) {
        let cmd = Command::new(&source, script_path)?;
        return Ok(eval_internal(&cmd, &script_args[1..]));
    }
    if script_args.first().map(|v| v == "___parallel___").unwrap_or(false) {
        return eval_parallel(&script_args[1..]);
    }
    let cmd = Command::new(&source, script_path)?;
    let mut args: Vec<String> = vec![cmd.root_name.clone()];
    args.extend(script_args.iter().cloned());
    let mut envs: HashMap<String, String> = std::env::vars().collect();
    if let Some(dotenv) = &cmd.dotenv {
        for (k, v) in load_dotenv_file(dotenv) {
            envs.entry(k).or_insert(v);
        }
    }
    let mut matcher = Matcher::new(&cmd, &args, false);
    matcher.set_script_path(script_path);
    matcher.set_term_width(utils::term_width());
    matcher.set_envs(envs.clone());
    let term_width = utils::term_width();
    match matcher.to_arg_values() {
        ArgValuesResult::Err(err, target) => {
            let (text, code) = match &err {
                MatchError::DisplayHelp => (target.render_help(term_width), 0),
                MatchError::DisplayVersion => (format!("{}\n", target.render_version()), 0),
                _ => (format!("{}\n", render_error(&err, target)), 1),
            };
            Ok(format!("command cat >&2 <<-'EOF' \n{text}EOF\nexit {code}\n"))
        }
        ArgValuesResult::Ok(values) => {
            let target = values.cmd;
            let mut vars = matcher.build_variables(&values, false);
            let mut argc_vars_list = vars.clone();
            if cmd.exist_hook_before {
                argc_vars_list.push("_argc_before".to_string());
            }
            if cmd.exist_hook_after {
                argc_vars_list.push("_argc_after".to_string());
            }
            let mut out = String::new();
            out.push_str(&format!("export ARGC_VARS={}\n", encode_vars(&argc_vars_list)));
            if let Some(dotenv) = &cmd.dotenv {
                out.push_str(DOTENV_FN);
                out.push('\n');
                out.push_str(&format!("_argc_load_dotenv {}\n", utils::escape_shell_word(dotenv)));
            }
            // env defaults
            for env in target.envs.iter() {
                if envs.contains_key(&env.id) {
                    continue;
                }
                if let Some(d) = &env.default {
                    let v = match d {
                        param::DefaultValue::Value(v) => utils::escape_shell_word(v),
                        param::DefaultValue::Fn(f) => format!("`{f}`"),
                    };
                    out.push_str(&format!("export {}={v}\n", env.id));
                }
            }
            out.push_str(&vars.join("\n"));
            out.push('\n');
            vars.clear();
            // require tools
            let mut tools: Vec<String> = Vec::new();
            for c in matcher.cmds().iter() {
                for t in c.require_tools.iter() {
                    if !tools.contains(t) {
                        tools.push(t.clone());
                    }
                }
            }
            if target.default_subcommand && !matcher.cmds().iter().any(|c| std::ptr::eq(*c, target)) {
                for t in target.require_tools.iter() {
                    if !tools.contains(t) {
                        tools.push(t.clone());
                    }
                }
            }
            if !tools.is_empty() {
                out.push('\n');
                out.push_str(REQUIRE_TOOLS_FN);
                out.push('\n');
                out.push_str(&format!("_argc_require_tools {}\n\n", tools.join(" ")));
            }
            if cmd.exist_hook_before {
                out.push_str("_argc_before\n");
            }
            let fn_name = if target.is_root {
                if target.exist_main_fn {
                    Some("main".to_string())
                } else {
                    None
                }
            } else {
                target.fn_name.clone()
            };
            if let Some(f) = fn_name {
                let mut call = f;
                let rendered: Vec<String> = values
                    .positional_args
                    .iter()
                    .map(|v| {
                        if v.starts_with('`') && v.ends_with('`') && v.len() > 2 {
                            v.clone()
                        } else {
                            utils::escape_shell_word(v)
                        }
                    })
                    .collect();
                if !rendered.is_empty() {
                    call.push(' ');
                    call.push_str(&rendered.join(" "));
                }
                out.push_str(&call);
                out.push('\n');
            }
            if cmd.exist_hook_after {
                out.push_str("_argc_after\n");
            }
            Ok(out)
        }
    }
}

fn eval_internal(cmd: &Command, args: &[String]) -> String {
    let fn_name = args.first().cloned().unwrap_or_default();
    let mut rest: Vec<String> = args[1.min(args.len())..].to_vec();
    if rest.is_empty() {
        rest.push("prog".to_string());
    }
    let matcher = Matcher::new(cmd, &rest, true);
    let values = matcher.to_arg_values_lenient();
    let vars = matcher.build_variables(&values, true);
    let mut out = String::new();
    out.push_str(&format!("export ARGC_VARS={}\n", encode_vars(&vars)));
    out.push_str(&vars.join("\n"));
    out.push('\n');
    let mut call = fn_name;
    let rendered: Vec<String> = values.positional_args.iter().map(|v| utils::escape_shell_word(v)).collect();
    if !rendered.is_empty() {
        call.push(' ');
        call.push_str(&rendered.join(" "));
    }
    out.push_str(&call);
    out.push_str("\nexit\n");
    out
}

fn eval_parallel(args: &[String]) -> Result<String, String> {
    if args.is_empty() {
        return Err("No parallel command".to_string());
    }
    let mut out = String::new();
    if let Ok(v) = std::env::var("ARGC_VARS") {
        if let Some(decoded) = utils::base64_decode(&v) {
            out.push_str(&String::from_utf8_lossy(&decoded));
        }
    }
    out.push_str(&utils::escape_shell_words(args));
    out.push('\n');
    Ok(out)
}
