pub const SHELLS: [&str; 8] = ["bash", "elvish", "fish", "nushell", "powershell", "xonsh", "zsh", "tcsh"];

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Shell {
    Bash,
    Elvish,
    Fish,
    Generic,
    Nushell,
    Powershell,
    Xonsh,
    Zsh,
    Tcsh,
}

impl Shell {
    pub fn parse(s: &str) -> Option<Shell> {
        Some(match s {
            "bash" => Shell::Bash,
            "elvish" => Shell::Elvish,
            "fish" => Shell::Fish,
            "generic" => Shell::Generic,
            "nushell" => Shell::Nushell,
            "powershell" => Shell::Powershell,
            "xonsh" => Shell::Xonsh,
            "zsh" => Shell::Zsh,
            "tcsh" => Shell::Tcsh,
            _ => return None,
        })
    }
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum CompColor {
    Flag,
    Option,
    Command,
    Default,
    Dir,
    File,
    Exe,
    Symlink,
}

impl CompColor {
    fn ansi(&self) -> &'static str {
        match self {
