            CompColor::Command => "35",
            CompColor::Default | CompColor::File => "39",
            CompColor::Dir => "1;34",
            CompColor::Exe => "1;32",
            CompColor::Symlink => "1;36",
        }
    }
    fn name(&self) -> &'static str {
        match self {
            CompColor::Flag => "cyan",
            CompColor::Option => "cyan bold",
            CompColor::Command => "magenta",
            CompColor::Default | CompColor::File => "default",
            CompColor::Dir => "blue bold",
            CompColor::Exe => "green bold",
            CompColor::Symlink => "cyan bold",
        }
    }
    fn generic(&self) -> &'static str {
        match self {
            CompColor::Flag => "cyan",
            CompColor::Option => "cyan,bold",
            CompColor::Command => "magenta",
            CompColor::Default | CompColor::File => "default",
            CompColor::Dir => "blue,bold",
            CompColor::Exe => "green,bold",
            CompColor::Symlink => "cyan,bold",
        }
    }
}

#[derive(Debug, Clone)]
pub struct Candidate {
    pub value: String,
    pub description: String,
    pub nospace: bool,
    pub color: CompColor,
}

fn truncate_description(desc: &str) -> String {
    let first = desc.split('\n').next().unwrap_or("");
    let chars: Vec<char> = first.chars().collect();
    if chars.len() > 80 {
        let take = chars.len().min(83);
        format!("{}...", chars[..take].iter().collect::<String>())
    } else {
        first.to_string()
    }
}

fn find_in_path(name: &str) -> Option<PathBuf> {
    let path = std::env::var_os("PATH")?;
    for dir in std::env::split_paths(&path) {
        let p = dir.join(name);
        if p.is_file() {
            return Some(p);
        }
    }
    None
}

pub fn compgen(shell_name: &str, script_path: &str, args: &[String]) -> Option<String> {
    let shell = Shell::parse(shell_name)?;
    if args.is_empty() {
        return None;
    }
    let mut internal = false;
    let (source, path): (String, String) = if script_path.is_empty() {
        if args[0] == "argc" {
            let use_internal = args
                .get(1)
                .map(|v| v.starts_with("--argc"))
                .unwrap_or(false);
            if use_internal {
                internal = true;
                (INTERNAL_ARGC_SCRIPT.to_string(), String::new())
            } else {
                match crate::find_argcfile() {
                    Some(p) => (
                        std::fs::read_to_string(&p).ok()?,
                        p.to_string_lossy().to_string(),
                    ),
                    None => {
                        internal = true;
                        (INTERNAL_ARGC_SCRIPT.to_string(), String::new())
                    }
                }
            }
        } else {
            match find_in_path(&args[0]) {
                Some(p) => (
                    std::fs::read_to_string(&p).unwrap_or_default(),
                    p.to_string_lossy().to_string(),
                ),
                None => (String::new(), String::new()),
            }
        }
    } else {
        (std::fs::read_to_string(script_path).ok()?, script_path.to_string())
    };
    let name_for_cmd = if path.is_empty() { args[0].clone() } else { path.clone() };
    let cmd = Command::new(&source, &name_for_cmd).ok()?;
    let mut matcher = Matcher::new(&cmd, args, true);
    if !path.is_empty() {
        matcher.set_script_path(&path);
    }
    let last_arg = args.last().cloned().unwrap_or_default();
    let (quote, last) = strip_quote(&last_arg);
    let mut ctx = CompContext {
        shell,
        internal,
        script_path: path.clone(),
        args: args.to_vec(),
        quote,
        last: last.to_string(),
        prefix: String::new(),
        filter: last.to_string(),
        candidates: Vec::new(),
        value_items: Vec::new(),
        delimiter_prefix: false,
    };
    generate(&matcher, &cmd, &mut ctx);
    Some(render(&mut ctx))
}

fn strip_quote(arg: &str) -> (Option<char>, &str) {
    if let Some(c) = arg.chars().next() {
        if c == '\'' || c == '"' {
            return (Some(c), &arg[1..]);
        }
    }
    (None, arg)
}

struct CompContext {
    shell: Shell,
    internal: bool,
    script_path: String,
    args: Vec<String>,
    quote: Option<char>,
    last: String,
    prefix: String,
    filter: String,
    candidates: Vec<Candidate>,
    value_items: Vec<String>, // __argc_value=XXX names
    delimiter_prefix: bool,
}

fn generate(matcher: &Matcher, cmd: &Command, ctx: &mut CompContext) {
    let (mcmd, arg_comp, split_at, positional_args, dash) = matcher.compgen_state();
    let _ = cmd;
    let _ = dash;
    match arg_comp {
        ArgComp::Any => {}
        ArgComp::FlagOrOption => {
            if !ctx.last.starts_with('-') {
                return;
            }
            list_flag_options(matcher, mcmd, ctx);
        }
        ArgComp::FlagOrOptionCombine(arg) => {
            combine_flag_options(matcher, mcmd, arg, ctx);
        }
        ArgComp::OptionValue(param, idx) => {
            let split = split_at.unwrap_or(0);
            let value_text = ctx.last[split.min(ctx.last.len())..].to_string();
            ctx.prefix = ctx.last[..split.min(ctx.last.len())].to_string();
            ctx.filter = value_text.clone();
            if let Some(d) = param.delimiter {
                if let Some(pos) = value_text.rfind(d) {
                    ctx.prefix.push_str(&value_text[..pos + d.len_utf8()]);
                    ctx.filter = value_text[pos + d.len_utf8()..].to_string();
                    ctx.delimiter_prefix = true;
                }
            }
            let nospace = param.delimiter.is_some();
            let notation = param
                .notations
                .get((*idx).min(param.notations.len().saturating_sub(1)))
                .cloned()
                .unwrap_or_default();
            if ctx.internal {
                match param.id.as_str() {
                    "argc-completions" => {
                        if *idx == 0 {
                            for s in SHELLS {
                                ctx.candidates.push(Candidate {
                                    value: s.to_string(),
                                    description: String::new(),
                                    nospace: false,
                                    color: CompColor::Default,
                                });
                            }
                        } else {
                            ctx.value_items.push("CMDS".to_string());
                        }
                        return;
                    }
                    "argc-compgen" => {
                        if *idx == 0 {
                            for s in SHELLS {
                                ctx.candidates.push(Candidate {
                                    value: s.to_string(),
                                    description: String::new(),
                                    nospace: false,
                                    color: CompColor::Default,
                                });
                            }
                        } else {
                            ctx.value_items.push("path".to_string());
                        }
                        return;
                    }
                    _ => {}
                }
            }
            add_choice_candidates(matcher, &param.choice, &notation, nospace, ctx);
        }
        ArgComp::Symbol(ch) => {
            ctx.prefix = ch.to_string();
            ctx.filter = ctx.last[ch.len_utf8().min(ctx.last.len())..].to_string();
            if let Some(sym) = mcmd.symbols.iter().find(|s| s.ch == *ch) {
                if let Some(choice) = &sym.choice {
                    add_choice_candidates(matcher, &Some(choice.clone()), "", false, ctx);
                }
            }
        }
        ArgComp::CommandOrPositional => {
            let n = positional_args.len();
            let mut cmd = mcmd;
            let mut positional_args: Vec<String> = positional_args.to_vec();
            if !cmd.subcommands.is_empty() {
                if let Some(sub) = cmd.find_default_subcommand() {
                    if n > 1 {
                        cmd = sub;
                    }
                }
            }
            if n == 0 {
                return;
            }
            let is_help_list = positional_args.first().map(|v| v == "help").unwrap_or(false) && n == 2 && !cmd.subcommands.is_empty();
            let list_subs = !cmd.subcommands.is_empty() && (n == 1 || is_help_list);
            // positional values
            if !is_help_list {
                let flags: Vec<bool> = cmd.positionals.iter().map(|p| p.multiple).collect();
                if cmd.positionals.is_empty() {
                    if cmd.subcommands.is_empty() || n > 1 {
                        ctx.value_items.push("path".to_string());
                    }
                } else {
                    let (ranges, extra) = match_positionals(&flags, n, dash);
                    if extra.is_none() {
                        // find param index containing the last arg
                        let last_index = n - 1;
                        let mut found: Option<usize> = None;
                        for (pi, (start, size)) in ranges.iter().enumerate() {
                            if last_index >= *start && last_index < start + size {
                                found = Some(pi);
                            }
                        }
                        if let Some(pi) = found {
                            let param = &cmd.positionals[pi];
                            ctx.filter = ctx.last.clone();
                            if let Some(d) = param.delimiter {
                                if let Some(pos) = ctx.last.rfind(d) {
                                    ctx.prefix = ctx.last[..pos + d.len_utf8()].to_string();
                                    ctx.filter = ctx.last[pos + d.len_utf8()..].to_string();
                                    ctx.delimiter_prefix = true;
                                }
                            }
                            let nospace = param.delimiter.is_some();
                            add_choice_candidates(matcher, &param.choice, &param.notation, nospace, ctx);
                        }
                    }
                }
            }
            if list_subs {
                let has_describe = cmd.subcommands.iter().any(|c| !c.describe.is_empty());
                for sub in cmd.subcommands.iter() {
                    let name = sub.name_str();
                    ctx.candidates.push(Candidate {
                        value: name,
                        description: truncate_description(&sub.describe),
                        nospace: false,
                        color: CompColor::Command,
                    });
                }
                ctx.candidates.push(Candidate {
                    value: "help".to_string(),
                    description: if has_describe {
                        "Show help for a command".to_string()
                    } else {
                        String::new()
                    },
                    nospace: false,
                    color: CompColor::Command,
                });
            }
            let _ = positional_args.drain(..);
        }
    }
}

fn list_flag_options(matcher: &Matcher, cmd: &Command, ctx: &mut CompContext) {
    for param in cmd.flag_options.iter() {
        let used = matcher.flag_option_used(param) && !param.multiple_occurs;
        for name in param.list_names() {
            if used && name != ctx.last {
                continue;
            }
            let (value, nospace) = if !param.flag && param.assigned {
                (format!("{name}="), true)
            } else if param.prefixed {
                (name.clone(), true)
            } else {
                (name.clone(), false)
            };
            ctx.candidates.push(Candidate {
                value,
                description: truncate_description(&param.describe),
                nospace,
                color: if param.flag { CompColor::Flag } else { CompColor::Option },
            });
        }
    }
}

fn combine_flag_options(matcher: &Matcher, cmd: &Command, arg: &str, ctx: &mut CompContext) {
    let chars: Vec<char> = arg.chars().collect();
    let last_char = *chars.last().unwrap();
    let last_param = cmd.flag_options.iter().find(|p| {
        let n = format!("-{last_char}");
        p.short_name.as_deref() == Some(&n) || (p.short_name.is_none() && p.long_name == n)
    });
    let last_is_flag = last_param.map(|p| p.flag).unwrap_or(false);
    if !last_is_flag {
        // behave like exact-match listing filtered by the arg
        list_flag_options(matcher, cmd, ctx);
        return;
    }
    let used_chars = matcher.used_short_chars();
    let mut combos: Vec<Candidate> = Vec::new();
    for param in cmd.flag_options.iter() {
        if param.is_help() || param.is_version() {
            continue;
        }
        let short = match &param.short_name {
            Some(s) => s.clone(),
            None => {
                if param.long_name.chars().count() == 2 && param.long_name.starts_with('-') {
                    param.long_name.clone()
                } else {
                    continue;
                }
            }
        };
        let c = match short.chars().nth(1) {
            Some(c) => c,
            None => continue,
        };
        if !param.multiple_occurs && (used_chars.contains(&c) || chars[1..].contains(&c)) {
            continue;
        }
        combos.push(Candidate {
            value: format!("{arg}{c}"),
            description: truncate_description(&param.describe),
            nospace: false,
            color: if param.flag { CompColor::Flag } else { CompColor::Option },
        });
    }
    if combos.len() == 1 {
        ctx.candidates.push(Candidate {
            value: arg.to_string(),
            description: String::new(),
            nospace: false,
            color: CompColor::Flag,
        });
    }
    ctx.candidates.extend(combos);
}

fn add_choice_candidates(
    matcher: &Matcher,
    choice: &Option<ChoiceValue>,
    notation: &str,
    nospace: bool,
    ctx: &mut CompContext,
) {
    match choice {
        Some(ChoiceValue::Values(values)) => {
            for v in values {
                ctx.candidates.push(Candidate {
                    value: v.clone(),
                    description: String::new(),
                    nospace,
                    color: CompColor::Default,
                });
            }
        }
        Some(ChoiceValue::Fn(f, _)) => {
            if ctx.script_path.is_empty() {
                return;
            }
            let mut envs = HashMap::new();
            envs.insert("ARGC_COMPGEN".to_string(), "1".to_string());
            envs.insert("ARGC_LAST_ARG".to_string(), ctx.args.last().cloned().unwrap_or_default());
            envs.insert("ARGC_CWORD".to_string(), ctx.filter.clone());
            let outputs = match run_param_fns(&ctx.script_path, &[f.as_str()], matcher.args(), envs) {
                Some(v) => v,
                None => return,
            };
            let mut seen: Vec<String> = Vec::new();
            let mut extra_prefix = String::new();
            let mut extra_suffix = String::new();
            let mut items: Vec<Candidate> = Vec::new();
            let mut directives: Vec<String> = Vec::new();
            for line in outputs[0].lines() {
                let line = line.trim();
                if line.is_empty() {
                    continue;
                }
                if line.starts_with("__argc_") {
                    if let Some(v) = line.strip_prefix("__argc_value=") {
                        ctx.value_items.push(v.to_string());
                    } else if let Some(v) = line.strip_prefix("__argc_prefix=") {
                        extra_prefix = v.to_string();
                    } else if let Some(v) = line.strip_prefix("__argc_suffix=") {
                        extra_suffix = v.to_string();
                    } else if let Some(v) = line.strip_prefix("__argc_filter=") {
                        ctx.filter = v.to_string();
                    }
                    directives.push(line.to_string());
                    continue;
                }
                let (value, desc) = match line.split_once('\t') {
                    Some((v, d)) => (v.trim().to_string(), d.trim().replace('\t', " ")),
                    None => (line.to_string(), String::new()),
                };
                if value.is_empty() || seen.contains(&value) {
                    continue;
                }
                seen.push(value.clone());
                items.push(Candidate {
                    value,
                    description: desc,
                    nospace,
                    color: CompColor::Default,
                });
            }
            if ctx.shell == Shell::Generic {
                for d in directives {
                    ctx.candidates.push(Candidate {
                        value: d,
                        description: String::new(),
                        nospace: false,
                        color: CompColor::Default,
                    });
                }
            }
            for mut item in items {
                item.value = format!("{extra_prefix}{}{extra_suffix}", item.value);
                ctx.candidates.push(item);
            }
            ctx.extra_prefix_len = extra_prefix.chars().count();
        }
        None => {
            if !notation.is_empty() {
                ctx.value_items.push(notation.to_string());
            }
        }
    }
}
