fn is_file_value(name: &str) -> Option<bool> {
    let lower = name.to_lowercase();
    if ["file", "path", "arg", "any"].iter().any(|k| lower.contains(k)) {
        return Some(false);
    }
    if ["dir", "folder"].iter().any(|k| lower.contains(k)) {
        return Some(true);
    }
    None
}

fn complete_files(filter: &str, dir_only: bool) -> Vec<(String, String, bool, CompColor)> {
    // returns (dir_part, name, is_dir, color)
    let (dir_part, name_part) = match filter.rfind('/') {
        Some(pos) => (&filter[..pos + 1], &filter[pos + 1..]),
        None => ("", filter),
    };
    let search_dir: PathBuf = if dir_part.is_empty() {
        PathBuf::from(".")
    } else if dir_part.starts_with("~/") || dir_part == "~" {
        match std::env::var("HOME") {
            Ok(home) => PathBuf::from(format!("{home}{}", &dir_part[1..])),
            Err(_) => PathBuf::from(dir_part),
        }
    } else {
        PathBuf::from(dir_part)
    };
    let mut out: Vec<(String, String, bool, CompColor)> = Vec::new();
    let entries = match std::fs::read_dir(&search_dir) {
        Ok(v) => v,
        Err(_) => return out,
    };
    for entry in entries.flatten() {
        let name = entry.file_name().to_string_lossy().to_string();
        if !name.starts_with(name_part) {
            continue;
        }
        if name.starts_with('.') && !name_part.starts_with('.') {
            continue;
        }
        let path = entry.path();
        let meta = match std::fs::metadata(&path) {
            Ok(m) => m,
            Err(_) => continue,
        };
        let is_dir = meta.is_dir();
        if dir_only && !is_dir {
            continue;
        }
        let symlink = std::fs::symlink_metadata(&path)
            .map(|m| m.file_type().is_symlink())
            .unwrap_or(false);
        let color = if is_dir {
            CompColor::Dir
        } else if symlink {
            CompColor::Symlink
        } else if is_executable(&meta) {
            CompColor::Exe
        } else {
            CompColor::File
        };
        out.push((dir_part.to_string(), name, is_dir, color));
    }
    out.sort_by(|a, b| {
        a.1.to_lowercase()
            .cmp(&b.1.to_lowercase())
            .then(a.1.cmp(&b.1))
    });
    out
}

#[cfg(unix)]
fn is_executable(meta: &std::fs::Metadata) -> bool {
    use std::os::unix::fs::PermissionsExt;
    meta.permissions().mode() & 0o111 != 0
}

#[cfg(not(unix))]
fn is_executable(_meta: &std::fs::Metadata) -> bool {
    false
}

fn render(ctx: &mut CompContext) -> String {
    let prefix = ctx.prefix.clone();
    let filter = ctx.filter.clone();
    let mut candidates: Vec<Candidate> = Vec::new();
    for c in ctx.candidates.iter() {
        if c.raw {
            candidates.push(c.clone());
            continue;
        }
        if !c.value.starts_with(&filter) {
            continue;
        }
        let mut c = c.clone();
        let display = c.display.clone().unwrap_or_else(|| c.value.clone());
        c.value = format!("{prefix}{}", c.value);
        c.display = Some(display);
        c.prefix_len = prefix.len();
        candidates.push(c);
    }
    for item in ctx.value_items.clone() {
        if ctx.shell == Shell::Generic {
            let mut c = Candidate::new(format!("__argc_value={item}"), String::new(), false, CompColor::Default);
            c.raw = true;
            candidates.push(c);
            continue;
        }
        let dir_only = match is_file_value(&item) {
            Some(v) => v,
            None => continue,
        };
        for (dir_part, name, is_dir, color) in complete_files(&filter, dir_only) {
            let value = if is_dir { format!("{name}/") } else { name.clone() };
            let mut c = Candidate::new(format!("{prefix}{dir_part}{value}"), String::new(), is_dir, color);
            c.display = Some(value);
            c.prefix_len = prefix.len() + dir_part.len();
            candidates.push(c);
        }
    }
    if ctx.quote.is_some() {
        for c in candidates.iter_mut() {
            c.nospace = true;
        }
    }
    let mut lines: Vec<String> = Vec::new();
    match ctx.shell {
        Shell::Generic => {
            for c in candidates.iter() {
                let mut line = c.value.clone();
                if c.nospace && !c.raw {
                    line.push('\0');
                }
                line.push_str(&format!("\t/color:{}", c.color.generic()));
                if !c.description.is_empty() {
                    line.push('\t');
                    line.push_str(&c.description);
                }
                lines.push(line);
            }
        }
        Shell::Bash => {
            render_bash(ctx, &candidates, &mut lines);
        }
        Shell::Zsh => {
            for c in candidates.iter() {
                let display = c.display.clone().unwrap_or_default();
                let mut value = zsh_escape(&c.value);
                if !c.nospace {
                    value.push(' ');
                }
                let mut desc_field = display.replace(':', "\\:");
                if !c.description.is_empty() {
                    desc_field.push(':');
                    desc_field.push_str(&c.description);
                }
                lines.push(format!("{value}\t{desc_field}\t{display}\t{}", c.color.ansi()));
            }
        }
        Shell::Fish => {
            for c in candidates.iter() {
                let mut value = c.value.clone();
                if let Some(q) = ctx.quote {
                    value = format!("{q}{value}");
                }
                if c.description.is_empty() {
                    lines.push(value);
                } else {
                    lines.push(format!("{value}\t{}", c.description));
                }
            }
        }
        Shell::Nushell => {
            for c in candidates.iter() {
                let mut value = nushell_quote(&c.value);
                if let Some(q) = ctx.quote {
                    value = format!("{q}{}", c.value);
                }
                if !c.nospace {
                    value.push(' ');
                }
                if c.description.is_empty() {
                    lines.push(value);
                } else {
                    lines.push(format!("{value}\t{}", c.description));
                }
            }
        }
        Shell::Powershell => {
            for c in candidates.iter() {
                let display = c.display.clone().unwrap_or_default();
                let raw_value = if ctx.delimiter_prefix {
                    c.value[c.prefix_len.min(c.value.len())..].to_string()
                } else {
                    c.value.clone()
                };
                let mut value = powershell_quote(&raw_value);
                if let Some(q) = ctx.quote {
                    value = format!("{q}{raw_value}");
                }
                let space = if c.nospace { "0" } else { "1" };
                lines.push(format!("{value}\t{space}\t{display}\t{}\t{}", c.description, c.color.ansi()));
            }
        }
        Shell::Elvish => {
            for c in candidates.iter() {
                let display = c.display.clone().unwrap_or_default();
                let mut value = c.value.clone();
                if let Some(q) = ctx.quote {
                    value = format!("{q}{value}");
                }
                let space = if c.nospace { "0" } else { "1" };
                lines.push(format!("{value}\t{space}\t{display}\t{}\t{}", c.description, c.color.name()));
            }
        }
        Shell::Xonsh => {
            for c in candidates.iter() {
                let display = c.display.clone().unwrap_or_default();
                let mut value = xonsh_quote(&c.value);
                if let Some(q) = ctx.quote {
                    value = format!("{q}{}", c.value);
                }
                let space = if c.nospace { "0" } else { "1" };
                lines.push(format!("{value}\t{space}\t{display}\t{}", c.description));
            }
        }
        Shell::Tcsh => {
            for c in candidates.iter() {
                let mut value = tcsh_escape(&c.value);
                if let Some(q) = ctx.quote {
                    value = format!("{q}{}", c.value);
                }
                let line = if c.description.is_empty() {
                    value
                } else {
                    format!("{value} ({})", c.description)
                };
                lines.push(line.replace(' ', "\u{2800}"));
            }
        }
    }
    let mut out = lines.join("\n");
    if !lines.is_empty() {
        out.push('\n');
    }
    out
}

fn common_prefix(values: &[&str]) -> String {
    if values.is_empty() {
        return String::new();
    }
    let first: Vec<char> = values[0].chars().collect();
    let mut len = first.len();
    for v in values.iter().skip(1) {
        let chars: Vec<char> = v.chars().collect();
        let mut i = 0;
        while i < len && i < chars.len() && chars[i] == first[i] {
            i += 1;
        }
        len = i;
    }
    first[..len].iter().collect()
}

fn bash_break(word: &str, value: &str) -> String {
    // truncate value according to bash COMP_WORDBREAKS found in word
    let mut cut: Option<usize> = None;
    for (i, c) in word.char_indices() {
        match c {
            '=' | ':' => cut = Some(i + 1),
            '@' => cut = Some(i),
            _ => {}
        }
    }
    match cut {
        Some(pos) if pos <= value.len() => value[pos..].to_string(),
        _ => value.to_string(),
    }
}

fn render_bash(ctx: &CompContext, candidates: &[Candidate], lines: &mut Vec<String>) {
    let word = ctx.last.clone();
    let filter_empty = ctx.filter.is_empty();
    let render_value = |c_value: &str, prefix_len: usize| -> String {
        let v = if filter_empty {
            c_value[prefix_len.min(c_value.len())..].to_string()
        } else {
            bash_break(&word, c_value)
        };
        match ctx.quote {
            Some(q) => {
                if filter_empty {
                    v
                } else {
                    format!("{q}{v}")
                }
            }
            None => bash_escape(&v),
        }
    };
    let non_raw: Vec<&Candidate> = candidates.iter().filter(|c| !c.raw).collect();
    if non_raw.len() > 1 {
        let values: Vec<&str> = non_raw.iter().map(|c| c.value.as_str()).collect();
        let common = common_prefix(&values);
        if common.chars().count() > word.chars().count() {
            lines.push(render_value(&common, non_raw[0].prefix_len));
            return;
        }
        for c in non_raw.iter() {
            let v = render_value(&c.value, c.prefix_len);
            if !c.description.is_empty() {
                lines.push(format!("{v} ({})", c.description));
            } else if c.nospace {
                lines.push(v);
            } else {
                lines.push(format!("{v} "));
            }
        }
    } else {
        for c in non_raw.iter() {
            let v = render_value(&c.value, c.prefix_len);
            if c.nospace {
                lines.push(v);
            } else {
                lines.push(format!("{v} "));
            }
        }
    }
}

fn bash_escape(value: &str) -> String {
    let mut out = String::new();
    for c in value.chars() {
        if matches!(c, '!' | '"' | '$' | '&' | '\'' | '(' | ')' | ';' | '<' | '>' | '\\' | '`' | '|' | ' ') {
            out.push('\\');
        }
        out.push(c);
    }
    out
}

fn zsh_escape(value: &str) -> String {
    let mut out = String::new();
    for c in value.chars() {
        if matches!(c, '!' | '"' | '$' | '&' | '\'' | '(' | ')' | '*' | ';' | '<' | '>' | '?' | '[' | '\\' | '`' | '|' | ' ') {
            out.push_str("\\\\");
        } else if c == ':' {
            out.push('\\');
        }
        out.push(c);
    }
    out
}

