use crate::command::Command;
use crate::param::{ChoiceValue, DefaultValue, FlagOptionParam};
use std::path::Path;

fn esc(text: &str) -> String {
    let mut out = String::new();
    let mut prev_nl = false;
    for c in text.chars() {
        if prev_nl && (c == '.' || c == '\'') {
            out.push_str("\\&");
        }
        prev_nl = c == '\n';
        match c {
            '\\' => out.push_str("\\\\"),
            '-' => out.push_str("\\-"),
            _ => out.push(c),
        }
    }
    out
}

fn bold(text: &str) -> String {
    format!("\\fB{}\\fR", esc(text))
}

fn italic(text: &str) -> String {
    format!("\\fI{}\\fR", esc(text))
}

fn control(name: &str, args: &[&str]) -> String {
    let mut out = format!(".{name}");
    for a in args {
        out.push(' ');
        if a.contains(' ') {
            out.push_str(&format!("\"{a}\""));
        } else {
            out.push_str(a);
        }
    }
    out.push('\n');
    out
}

fn render_option_name(param: &FlagOptionParam) -> String {
    let mut parts: Vec<String> = Vec::new();
    if let Some(s) = &param.short_name {
        parts.push(bold(s));
    }
    parts.push(bold(&param.long_name));
    let mut out = parts.join(", ");
    if !param.flag {
        if param.notations.len() == 1 {
            let n = italic(&param.notations[0]);
            let v = if param.multiple_occurs {
                if param.required {
                    format!("<{n}>...")
                } else {
                    format!("[{n}]...")
                }
            } else if param.required {
                format!("<{n}>")
            } else {
                n
            };
            out.push('=');
            out.push_str(&v);
        } else {
            for n in param.notations.iter() {
                out.push(' ');
                out.push_str(&italic(n));
            }
        }
    }
    if let Some(DefaultValue::Value(v)) = &param.default {
        out.push_str(&format!(" [default: {}]", esc(v)));
    }
    out
}

fn render_body(describe: &str, choice: &Option<ChoiceValue>) -> String {
    let mut out = String::new();
    if describe.is_empty() {
        out.push('\n');
    } else {
        for line in describe.split('\n') {
            out.push_str(".br\n");
            out.push_str(&esc(line));
            out.push('\n');
        }
    }
    if let Some(ChoiceValue::Values(values)) = choice {
        if !describe.is_empty() {
            out.push_str(".br\n\n");
        }
        out.push_str(".br\n");
        out.push_str(&format!(
            "[{}{}]\n",
            italic("possible values: "),
            esc(&values.join(", "))
        ));
    }
    out
}

fn render_page(cmd: &Command, section: &str) -> String {
    let full = cmd.full_name();
    let version = cmd.version.clone().unwrap_or_else(|| "0.0.0".to_string());
    let mut out = String::new();
    out.push_str(&control(
        "TH",
        &[&full.to_uppercase(), section, "", &format!("{full} {version}"), ""],
    ));
    out.push_str(&control("SH", &["NAME"]));
    let head = cmd.describe_head();
    if head.is_empty() {
        out.push_str(&format!("{}\n", esc(&full)));
    } else {
        out.push_str(&format!("{} \\- {}\n", esc(&full), esc(head)));
    }
    out.push_str(&control("SH", &["SYNOPSIS"]));
    let usage = cmd.render_usage();
    let cmd_paths = cmd.cmd_paths_str();
    let rest = usage
        .strip_prefix(&format!("USAGE: {cmd_paths}"))
        .unwrap_or("")
        .to_string();
    out.push_str(&format!("{}{}\n", bold(&cmd_paths), rest));
    if cmd.describe.contains('\n') {
        out.push_str(&control("SH", &["DESCRIPTION"]));
        for line in cmd.describe.split('\n') {
            out.push_str(".br\n");
            out.push_str(&esc(line));
            out.push('\n');
        }
    }
    if !cmd.positionals.is_empty() || cmd.has_user_flag_options() || (!cmd.flag_options.is_empty() && cmd.subcommands.is_empty() && !cmd.positionals.is_empty()) {
        out.push_str(&control("SH", &["OPTIONS"]));
        for param in cmd.flag_options.iter() {
            out.push_str(".TP\n");
            out.push_str(&render_option_name(param));
            out.push('\n');
            out.push_str(&render_body(&param.describe, &param.choice));
        }
        for param in cmd.positionals.iter() {
            out.push_str(".TP\n");
            let n = italic(&param.notation);
            let mut name = if param.required {
                format!("<{n}>")
            } else {
                format!("[{n}]")
            };
            if param.multiple {
                name.push_str("...");
            }
            if let Some(DefaultValue::Value(v)) = &param.default {
                name.push_str(&format!(" [default: {}]", esc(v)));
            }
            out.push_str(&name);
            out.push('\n');
            out.push_str(&render_body(&param.describe, &param.choice));
        }
    }
    if !cmd.subcommands.is_empty() {
        out.push_str(&control("SH", &["SUBCOMMANDS"]));
        for sub in cmd.subcommands.iter() {
            out.push_str(".TP\n");
            let mut text = format!("{}({section})", sub.full_name());
            if !sub.describe.is_empty() {
                text.push('\n');
                text.push_str(&sub.describe);
            }
            out.push_str(&esc(&text));
            out.push('\n');
        }
    }
    if !cmd.envs.is_empty() {
        out.push_str(&control("SH", &["ENVIRONMENT VARIABLES:"]));
        for env in cmd.envs.iter() {
            out.push_str(".TP\n");
            let mut name = italic(&env.id);
            if env.required {
                name.push('*');
            }
            if let Some(DefaultValue::Value(v)) = &env.default {
                name.push_str(&format!(" [default: {}]", esc(v)));
            }
            out.push_str(&name);
            out.push('\n');
            out.push_str(&render_body(&env.describe, &env.choice));
        }
    }
    if let Some(v) = &cmd.version {
        out.push_str(&control("SH", &["VERSION"]));
        out.push_str(&esc(v));
        out.push('\n');
    }
    out
}

fn collect<'a>(cmd: &'a Command, out: &mut Vec<&'a Command>) {
    out.push(cmd);
    for sub in cmd.subcommands.iter() {
        collect(sub, out);
    }
}

pub fn mangen(cmd: &Command, outdir: &str) -> i32 {
    let section = cmd.man_section.clone().unwrap_or_else(|| "1".to_string());
    let dir = Path::new(outdir);
    if let Err(e) = std::fs::create_dir_all(dir) {
        eprintln!("Failed to create dir at '{outdir}'\n\nCaused by:\n    {e}");
        return 1;
    }
    let mut cmds = Vec::new();
    collect(cmd, &mut cmds);
    for c in cmds {
        let name = format!("{}.{section}", c.full_name());
        let path = dir.join(&name);
        let content = render_page(c, &section);
        if let Err(e) = std::fs::write(&path, content) {
            eprintln!("Failed to write man page at '{}'\n\nCaused by:\n    {e}", path.display());
            return 1;
        }
        println!("saved {}", path.display());
    }
    0
}
