        utils.push('\n');
    }
    if flags.validate_choices {
        utils.push_str(UTIL_VALIDATE_CHOICES);
        utils.push('\n');
    }
    if flags.check_bool {
        utils.push_str(UTIL_CHECK_BOOL);
        utils.push('\n');
    }
    if cmd.dotenv.is_some() {
        utils.push_str(UTIL_LOAD_DOTENV);
        utils.push('\n');
    }
    if flags.maybe_flag_option {
        utils.push_str(UTIL_MAYBE_FLAG_OPTION);
        utils.push('\n');
    }
    if flags.require_params_options || flags.require_params_envs {
        utils.push_str(UTIL_REQUIRE_PARAMS);
        utils.push('\n');
    }
    if flags.require_tools {
        utils.push_str(UTIL_REQUIRE_TOOLS);
        utils.push('\n');
    }
    utils.push_str(UTIL_DIE);

    let block = format!(
        "# ARGC-BUILD {{\n# This block was generated by argc (https://github.com/sigoden/argc).\n# Modifying it manually is not recommended\n\n{run}\n{body}{utils}\n_argc_run \"$@\"\n\n# ARGC-BUILD }}"
    );

    // replace the eval line
    let mut out_lines: Vec<String> = Vec::new();
    let mut replaced = false;
    for line in source.lines() {
        if !replaced && is_eval_line(line) {
            out_lines.push(block.clone());
            replaced = true;
        } else {
            out_lines.push(line.to_string());
        }
    }
    let mut out = out_lines.join("\n");
    if !replaced {
        if !out.is_empty() && !out.ends_with('\n') {
            out.push('\n');
        }
        out.push('\n');
        out.push_str(&block);
    }
    out.push('\n');
    out
}

fn is_eval_line(line: &str) -> bool {
    let t = line.trim();
    t.starts_with("eval") && t.contains("argc --argc-eval")
}

fn collect<'a>(cmd: &'a Command, out: &mut Vec<&'a Command>) {
    out.push(cmd);
    for sub in cmd.subcommands.iter() {
        collect(sub, out);
    }
}

fn build_usage(cmd: &Command) -> String {
    let help = cmd.render_help(None);
    let help = help.trim_end_matches('\n');
    format!(
        "_argc_usage{}() {{\n    cat <<-'EOF'\n{help}\nEOF\n    exit\n}}\n",
        fn_suffix(cmd)
    )
}

fn build_version(cmd: &Command) -> String {
    format!(
        "_argc_version{}() {{\n    echo {}\n    exit\n}}\n",
        fn_suffix(cmd),
        cmd.render_version()
    )
}

fn build_parse(cmd: &Command, root: &Command, flags: &mut Flags) -> String {
    let suffix = fn_suffix(cmd);
    let mut out = String::new();
    out.push_str(&format!("_argc_parse{suffix}() {{\n"));
    out.push_str("    local _argc_key _argc_action\n");
    let subcmds = cmd.list_subcommand_names().join(", ");
    out.push_str(&format!("    local _argc_subcmds=\"{subcmds}\"\n"));
    out.push_str("    while [[ $_argc_index -lt $_argc_len ]]; do\n");
    out.push_str("        _argc_item=\"${argc__args[_argc_index]}\"\n");
    out.push_str("        _argc_key=\"${_argc_item%%=*}\"\n");
    out.push_str("        case \"$_argc_key\" in\n");
    // help
    if let Some(h) = cmd.flag_options.iter().find(|f| f.is_help()) {
        let mut pat = "--help | -help".to_string();
        if let Some(s) = &h.short_name {
            pat.push_str(&format!(" | {s}"));
        }
        out.push_str(&format!("        {pat})\n            _argc_usage{suffix}\n            ;;\n"));
    }
    if let Some(v) = cmd.flag_options.iter().find(|f| f.is_version()) {
        let mut pat = "--version | -version".to_string();
        if let Some(s) = &v.short_name {
            pat.push_str(&format!(" | {s}"));
        }
        out.push_str(&format!("        {pat})\n            _argc_version{suffix}\n            ;;\n"));
    }
    out.push_str("        --)\n            _argc_dash=\"${#argc__positionals[@]}\"\n            argc__positionals+=(\"${argc__args[@]:$((_argc_index + 1))}\")\n            _argc_index=$_argc_len\n            break\n            ;;\n");
    let signs = cmd.flag_option_signs();
    let user_options: Vec<&FlagOptionParam> = cmd
        .flag_options
        .iter()
        .filter(|f| !f.is_help() && !f.is_version())
        .collect();
    for param in user_options.iter() {
        out.push_str(&build_flag_option_case(param, &signs, flags));
    }
    for sub in cmd.subcommands.iter() {
        let mut names = vec![sub.name_str()];
        names.extend(sub.aliases.iter().cloned());
        out.push_str(&format!(
            "        {})\n            _argc_index=$((_argc_index + 1))\n            _argc_action=_argc_parse{}\n            break\n            ;;\n",
            names.join(" | "),
            fn_suffix(sub)
        ));
    }
    if !cmd.subcommands.is_empty() {
        out.push_str("        help)\n            local help_arg=\"${argc__args[$((_argc_index + 1))]:-}\"\n            case \"$help_arg\" in\n");
        for sub in cmd.subcommands.iter() {
            let mut names = vec![sub.name_str()];
            names.extend(sub.aliases.iter().cloned());
            out.push_str(&format!(
                "            {})\n                _argc_usage{}\n                ;;\n",
                names.join(" | "),
                fn_suffix(sub)
            ));
        }
        out.push_str(&format!("            \"\")\n                _argc_usage{suffix}\n                ;;\n"));
        out.push_str("            *)\n                _argc_die \"error: invalid value \\`$help_arg\\` for \\`<command>\\`\"$'\\n'\"  [possible values: $_argc_subcmds]\"\n                ;;\n            esac\n            ;;\n");
        out.push_str(&format!(
            "        *)\n            _argc_die \"error: \\`{}\\` requires a subcommand but one was not provided\"$'\\n'\"  [subcommands: $_argc_subcmds]\"\n            ;;\n",
            cmd.full_name()
        ));
    } else {
        out.push_str("        *)\n");
        if !user_options.is_empty() {
            flags.maybe_flag_option = true;
            out.push_str(&format!(
                "            if _argc_maybe_flag_option \"{signs}\" \"$_argc_item\"; then\n                _argc_die \"error: unexpected argument \\`$_argc_key\\` found\"\n            fi\n"
            ));
        }
        out.push_str("            argc__positionals+=(\"$_argc_item\")\n            _argc_index=$((_argc_index + 1))\n            ;;\n");
    }
    out.push_str("        esac\n    done\n");
    // env bindings for options
    for param in user_options.iter() {
        if let Some(env) = &param.env {
            let var = param.var_name();
            out.push_str(&format!("    if [[ -z \"${{{var}:-}}\" ]] && [[ -n \"${{{env}:-}}\" ]]; then        \n"));
            if param.flag {
                flags.check_bool = true;
                out.push_str(&format!(
                    "        if _argc_check_bool {env} \"{}\"; then\n            {var}=1\n        fi\n",
                    param.long_name
                ));
            } else {
                if let Some(d) = param.delimiter {
                    out.push_str(&format!("        IFS=\"{d}\" read -r -a _argc_env_values <<<\"${env}\"\n"));
                } else {
                    out.push_str(&format!("        _argc_env_values=(\"${env}\")\n"));
                }
                if let Some(choice) = &param.choice {
                    if let Some(expr) = choices_expr(choice) {
                        flags.validate_choices = true;
                        out.push_str(&format!(
                            "        _argc_validate_choices 'environment variable `{env}` that bound to `{}`' {expr} \"${{_argc_env_values[@]}}\"\n",
                            param.render_long_with_notations()
                        ));
                    }
                }
                if param.multiple_values {
                    out.push_str(&format!("        {var}=(\"${{_argc_env_values[@]}}\")\n"));
                } else {
                    out.push_str(&format!("        {var}=\"${{_argc_env_values[0]}}\"\n"));
                }
            }
            out.push_str("    fi\n");
        }
    }
    // defaults
    for param in user_options.iter() {
        if let Some(d) = &param.default {
            let var = param.var_name();
            out.push_str(&format!(
                "    if [[ -z \"${{{var}:-}}\" ]]; then\n        {var}={}\n    fi\n",
                default_expr(d)
            ));
        }
    }
    // required
    let required: Vec<String> = user_options
        .iter()
        .filter(|p| p.required)
        .map(|p| format!("'{}:{}'", p.var_name(), p.render_long_with_notations()))
        .collect();
    if !required.is_empty() {
        flags.require_params_options = true;
        out.push_str(&format!("    _argc_required_flag_options+=({})\n", required.join(" ")));
    }
    // tools
    let mut tools: Vec<String> = Vec::new();
    for c in root_chain(root, cmd) {
        for t in c.require_tools.iter() {
            if !tools.contains(t) {
                tools.push(t.clone());
            }
        }
    }
    if !tools.is_empty() {
        out.push_str(&format!("    _argc_tools=({})\n", tools.join(" ")));
    }
    out.push_str("    if [[ -n \"${_argc_action:-}\" ]]; then\n        $_argc_action\n    else\n");
    let fn_name = if cmd.is_root {
        if cmd.exist_main_fn {
            Some("main".to_string())
        } else {
            None
        }
    } else {
        cmd.fn_name.clone()
    };
    if !cmd.subcommands.is_empty() && fn_name.is_none() {
        out.push_str(&format!("        _argc_usage{suffix}\n"));
    } else {
        if let Some(f) = &fn_name {
            out.push_str(&format!("        argc__fn={f}\n"));
        }
        out.push_str(&format!(
            "        if [[ \"${{argc__positionals[0]:-}}\" == \"help\" ]] && [[ \"${{#argc__positionals[@]}}\" -eq 1 ]]; then\n            _argc_usage{suffix}\n        fi\n"
        ));
        if !cmd.positionals.is_empty() {
            flags.match_positionals = true;
            let ps: Vec<String> = cmd
                .positionals
                .iter()
                .map(|p| if p.multiple { "1".to_string() } else { "0".to_string() })
                .collect();
            out.push_str(&format!("        _argc_match_positionals {}\n", ps.join(" ")));
            out.push_str("        local values_index values_size\n");
            for (i, p) in cmd.positionals.iter().enumerate() {
                out.push_str(&build_positional(p, i, flags));
            }
        }
        out.push_str(&build_envs(&cmd.envs, flags));
    }
    out.push_str("    fi\n}\n");
    out
}

fn root_chain<'a>(root: &'a Command, cmd: &'a Command) -> Vec<&'a Command> {
    // find the path from root to cmd
    let mut chain = vec![root];
    let mut cur = root;
    for name in cmd.paths[1..].iter() {
        if let Some(sub) = cur.subcommands.iter().find(|c| c.name.as_deref() == Some(name.as_str())) {
            chain.push(sub);
            cur = sub;
        }
    }
    chain
}

fn build_flag_option_case(param: &FlagOptionParam, signs: &str, flags: &mut Flags) -> String {
    let mut out = String::new();
    let mut names = vec![param.long_name.clone()];
    if let Some(s) = &param.short_name {
        names.push(s.clone());
    }
    out.push_str(&format!("        {})\n", names.join(" | ")));
    let var = param.var_name();
    let long = &param.long_name;
    if param.flag {
        out.push_str(&format!(
            "            if [[ \"$_argc_item\" == *=* ]]; then\n                _argc_die \"error: flag \\`{long}\\` don't accept any value\"\n            fi\n            _argc_index=$((_argc_index + 1))\n"
        ));
        if param.multiple_occurs {
            out.push_str(&format!(
                "            if [[ -n \"${{{var}:-}}\" ]]; then\n                {var}=$(({var} + 1))\n            else\n                {var}=1\n            fi\n"
            ));
        } else {
            out.push_str(&format!(
                "            if [[ -n \"${{{var}:-}}\" ]]; then\n                _argc_die \"error: the argument \\`{long}\\` cannot be used multiple times\"\n            else\n                {var}=1\n            fi\n"
            ));
        }
    } else {
        flags.take_args = true;
        let render = param.render_long_with_notations();
        let (min, max) = param.num_args;
        let signs_arg = if param.terminated { "" } else { signs };
        let delimiter = param.delimiter.map(|c| c.to_string()).unwrap_or_default();
        let take = format!("_argc_take_args \"{render}\" {min} {max} \"{signs_arg}\" \"{delimiter}\"");
        if param.assigned {
            out.push_str(&format!(
                "            if [[ \"$_argc_key\" == \"$_argc_item\" ]]; then\n                _argc_die \"error: incorrect number of values for \\`{render}\\`\"\n            else\n                {take}\n            fi\n"
            ));
        } else {
            out.push_str(&format!("            {take}\n"));
        }
        out.push_str("            _argc_index=$((_argc_index + _argc_take_args_len + 1))\n");
        if let Some(choice) = &param.choice {
            if let Some(expr) = choices_expr(choice) {
                flags.validate_choices = true;
                out.push_str(&format!(
                    "            _argc_validate_choices '`<{}>`' {expr} \"${{_argc_take_args_values[@]}}\"\n",
                    param.render_first_notation()
                ));
            }
        }
        if param.multiple_values {
            out.push_str(&format!("            {var}+=(\"${{_argc_take_args_values[@]}}\")\n"));
        } else {
            out.push_str(&format!(
                "            if [[ -z \"${{{var}:-}}\" ]]; then\n                {var}=\"${{_argc_take_args_values[0]:-}}\"\n            else\n                _argc_die \"error: the argument \\`{long}\\` cannot be used multiple times\"\n            fi\n"
            ));
        }
    }
    out.push_str("            ;;\n");
    out
}

fn build_positional(p: &PositionalParam, index: usize, flags: &mut Flags) -> String {
    let mut out = String::new();
    let var = p.var_name();
    out.push_str(&format!(
        "        IFS=: read -r values_index values_size <<<\"${{_argc_match_positionals_values[{index}]:-}}\"\n"
    ));
    out.push_str("        if [[ -n \"$values_index\" ]]; then\n");
    if p.multiple {
        if let Some(d) = p.delimiter {
            flags.split_positionals = true;
            out.push_str(&format!(
                "            _argc_split_positionals \"$values_index\" \"$values_size\" \"{d}\"\n            {var}=(\"${{_argc_split_positionals_values[@]}}\")\n"
            ));
        } else {
            out.push_str(&format!("            {var}=(\"${{argc__positionals[@]:values_index:values_size}}\")\n"));
        }
    } else {
        out.push_str(&format!("            {var}=\"${{argc__positionals[values_index]}}\"\n"));
    }
    let choice_expr = p.choice.as_ref().and_then(choices_expr);
    if let Some(expr) = &choice_expr {
        flags.validate_choices = true;
        let values = if p.multiple {
            format!("\"${{{var}[@]}}\"")
        } else {
            format!("\"${var}\"")
        };
        out.push_str(&format!(
            "            _argc_validate_choices '`{}`' {expr} {values}\n",
            p.render_notation()
        ));
    }
    if let Some(env) = &p.env {
        out.push_str(&format!("        elif [[ -n \"${{{env}:-}}\" ]]; then            \n"));
        if let Some(d) = p.delimiter {
            out.push_str(&format!("            IFS=\"{d}\" read -r -a _argc_env_values <<<\"${env}\"\n"));
        } else {
            out.push_str(&format!("            _argc_env_values=(\"${env}\")\n"));
        }
        if let Some(expr) = &choice_expr {
            out.push_str(&format!(
                "            _argc_validate_choices 'environment variable `{env}` that bound to `{}`' {expr} \"${{_argc_env_values[@]}}\"\n",
                p.render_notation()
            ));
        }
        if p.multiple {
            out.push_str(&format!("            {var}=(\"${{_argc_env_values[@]}}\")\n"));
        } else {
            out.push_str(&format!("            {var}=\"${{_argc_env_values[0]}}\"\n"));
        }
        out.push_str("            argc__positionals+=(\"${_argc_env_values[@]}\")\n");
    }
    if let Some(d) = &p.default {
        out.push_str(&format!(
            "        else\n            {var}={}\n            argc__positionals+=(\"${var}\")\n",
            default_expr(d)
        ));
    } else if p.required {
        out.push_str(&format!(
            "        else\n            _argc_die \"error: the required environments \\`{}\\` were not provided\"\n",
            p.render_notation()
        ));
    }
    out.push_str("        fi\n");
    out
}

fn build_envs(envs: &[EnvParam], flags: &mut Flags) -> String {
    let mut out = String::new();
    let required: Vec<String> = envs
        .iter()
        .filter(|e| e.required)
        .map(|e| format!("{}:{}", e.id, e.id))
        .collect();
    if !required.is_empty() {
        out.push_str(&format!("        _argc_required_envs=({})\n", required.join(" ")));
    }
    for env in envs.iter() {
        let name = &env.id;
        let choice_expr = env.choice.as_ref().and_then(choices_expr);
        if let Some(expr) = &choice_expr {
            flags.validate_choices = true;
        }
        match (&env.default, &choice_expr) {
            (Some(d), Some(expr)) => {
                out.push_str(&format!(
                    "        if [[ -z \"${{{name}:-}}\" ]]; then\n            export {name}={}\n        else\n            _argc_validate_choices 'environment variable `{name}`' {expr} \"${name}\"\n        fi\n",
                    default_expr(d)
                ));
            }
            (Some(d), None) => {
                out.push_str(&format!(
                    "        if [[ -z \"${{{name}:-}}\" ]]; then\n            export {name}={}\n        fi\n",
                    default_expr(d)
                ));
            }
            (None, Some(expr)) => {
                out.push_str(&format!(
                    "        if [[ -n \"${{{name}:-}}\" ]]; then\n            _argc_validate_choices 'environment variable `{name}`' {expr} \"${name}\"\n        fi\n"
                ));
            }
            (None, None) => {}
        }
    }
    out
}
